import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст преподобному Іоанну Дамаскину","e":"Akathist to our Venerable Father John of Damascus","secs":[{"h":"Кондак 1","ps":["Ізбра́ннаго сосу́да благода́ті Бо́жия, Іоа́нна Богохва́льнаго, притеце́м всі восхвали́ти, от Дама́ська у́бо гра́да звізду́ всесві́тло возше́дшую, Вселе́нськия же Це́ркве свирі́ль приснопою́щую Боже́ственних та́їн і́стину, пренебре́гшаго сла́ву ми́ра сла́ви ра́ди Христа́ Бо́га, да вознесе́м єму́ моли́тву ра́дованія:","Ра́дуйся, преподо́бне Іоа́нне, Це́ркве учи́телю сладкогла́сний і прему́дрий."]},{"h":"Ікос 1","ps":["Ангелонра́вноє житіє́ предпоче́т, Іоа́нне благознамени́ті, прине́сл єси́ же́ртву Христу́ великосано́вния жи́зні отрече́нія, си́це і от му́дрости челові́чі поче́рп, найпа́че возлюби́л єси́ Бо́жия прему́дрости сла́дость, і в пусти́ні смире́нно все́лься, із'ясни́л єси́ пра́вия ві́ри висо́т простоту́. Сего́ ра́ди я́ко Боже́ственних уче́ній істо́чнику взива́єм ті:","Ра́дуйся, світи́льниче Боже́ственнаго сві́та, сія́яй в нощі́ неві́рія;","ра́дуйся, побо́рниче і́стинния ві́ри, умудря́яй словеси́ Богопозна́нія.","Ра́дуйся, благознамени́таго ро́да о́трасле;","ра́дуйся, смиренному́драго преподо́бія о́бразе.","Ра́дуйся, процві́тшая во среді́ ага́рян христия́нськая похвало́;","ра́дуйся, во тщесла́внем ми́рі прозя́бшеє кро́тости Христо́ви преподо́біє.","Ра́дуйся, от филосо́фов ми́ра науче́нний;","ра́дуйся, от Прему́дрости Бо́жия умудре́нний.","Ра́дуйся, я́ко возда́л єси́ Бо́жиє Бо́гові;","ра́дуйся, я́ко презрі́л єси́ кра́сная ца́рськая.","Ра́дуйся, благода́ті Бо́жия тезоімені́те;","ра́дуйся, Ца́рства ві́чнаго наслі́дниче.","Ра́дуйся, преподо́бне Іоа́нне, Це́ркве учи́телю сладкогла́сний і прему́дрий."]},{"h":"Кондак 2","ps":["Ви́дя Бог, я́ко сі́м'я, Їм сі́янноє, на до́бру зе́млю паде́ і хо́щеть плод многобога́ть принести́, упа́сл єсть дом твой, Іоа́нне Дамаски́не, роди́телев, в Христо́ві ві́рі утвержде́н, я́ко да неудобоприя́тну те́рнію яви́ть в нем Богоприя́тную розгу́, всеми́рно пісносло́в'ящую: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зума високому́дріє посрамля́ється, ви́дящим нам пе́рваго сові́тника власти́теля ага́рянськаго, власть во страні́ інове́рней ве́лію іму́ща, уничиже́нним же і гони́мим приліжа́ща се́рдцем, оби́димим і досажда́ємим помога́юща. Ті́мже і ни́ні припаде́м ко Іоа́нну, о нас печа́льнику, да ни усли́шить к нему́ вопію́щия:","Ра́дуйся, христолюби́вия па́стви благи́й упра́вителю;","ра́дуйся, ангелоподо́бний в біда́х су́щим храни́телю.","Ра́дуйся, а́ки до́брий самаряни́н больни́м прилежа́вий;","ра́дуйся, благи́ми ді́ли Христа́ пропові́давий.","Ра́дуйся, рабо́тати Бо́гові в безмо́лвії возжелі́вий;","ра́дуйся, оба́че кро́тці повину́вийся власте́м, да послу́жиши держа́ві твоє́й.","Ра́дуйся, вся́ку власть я́ко от Бо́га су́щу почита́вий;","ра́дуйся, от смире́нія вели́кая обріта́вий.","Ра́дуйся, я́ко ро́да твоєго́ сла́ву вельми́ умно́жил єси́;","ра́дуйся, превозше́дий в ра́зумі наста́вников і сро́дников твої́х.","Ра́дуйся, я́ко во́лю се́рдця твоєго́ во́лі Бо́жії приклони́л єси́;","ра́дуйся, я́ко ві́ри твоєя́ огнь в се́рдці твоє́м при́сно пламене́ющ вся́ко соблю́л єси́.","Ра́дуйся, преподо́бне Іоа́нне, Це́ркве учи́телю сладкогла́сний і прему́дрий."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго подви́женний, Іоа́нне Богопослу́шне, царя́ іконобо́рця не убоя́лся єси́: подо́б'я бо ся Іоа́нну Предте́чі, ре́вностнаго словесе́ не удержа́л єси́, да научи́ши лю́ди, кла́няющеся во іко́ні Первоо́бразу, взива́ти Бо́гові: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я внутр себі́ Боже́ственния сла́ви ре́вность, возви́сил єси́ глас твой, Іоа́нне Дамаски́не, і писа́ньми обличи́л єси́ ху́льники церко́вния, да отщети́ться тіх зломи́сліє. Сих ра́ди би́вших о тебі́, сла́вне, сла́вим тя:","Ра́дуйся, пе́рваго честна́го богосло́вія до́брий послі́дователю;","ра́дуйся, вне́млющих да́же до ни́ні слове́сним млеко́м пита́телю.","Ра́дуйся, сло́ва Бо́жия меч взе́мий, я́ко да єреті́чеськаго мудрова́нія главу́ усече́ши;","ра́дуйся, Преда́нія церко́внаго преє́мниче, і́мже ві́ри ізміне́нія ізбі́гнеши.","Ра́дуйся, ві́ру Христо́ву сло́вом із'ясни́вий;","ра́дуйся, прему́драя небе́сних словеси́ му́дрости земноро́дних ізложи́вий.","Ра́дуйся, гро́мов гла́се богосло́вствуяй;","ра́дуйся, сло́ва Бо́жия бога́тство некра́домоє.","Ра́дуйся, церко́внаго зда́нія пли́нфо несокруши́мая;","ра́дуйся, ні єди́но от вра́жия ле́сти поколе́блемий.","Ра́дуйся, основа́нія Богому́дрих муже́й проба́вителю;","ра́дуйся, благоглаго́ливих отце́в сораде́телю.","Ра́дуйся, преподо́бне Іоа́нне, Це́ркве учи́телю сладкогла́сний і прему́дрий."]},{"h":"Кондак 4","ps":["Бу́ри злоко́зненния клевети́ восприя́л єси́ обстоя́ніє, преподо́бне богосло́ве, богосло́вія ра́ди твоєго́. Се єди́н цар іно́му подо́біє письма́ твоєго́ пи́шеть, я́ко а́ще преда́тельство мнил єси́ в нем: се лжехристо́в Христо́ва сараци́ну предає́ть на казнь, Іу́ди подража́тель, да я́ко умолча́ть уста́, глаго́лющая пра́во: Аллилу́я."]},{"h":"Ікос 4","ps":["Благоусли́шася наві́т о тебі́ во у́шію царя́ Дама́скова: оглаго́льству бо подло́жния ха́ртії ві́ру ять, ніка́ко оправда́ній словесе́ неви́ннаго Боголю́бця послу́ша повели́тель: на усіче́ніє десни́ці предаде́ тя, є́юже пи́сьменне всі ху́лящії Бо́га бя́ху облича́лися, но сего́ ра́ди тебе́, о Іоа́нні, воспоє́м:","Ра́дуйся, ві́дий, я́ко на пра́во сла́в'ящия Бо́га ко́зні вра́жия ізоби́лують;","ра́дуйся, тіх дово́льноє да́же до кро́ве ді́йство претерпі́вий.","Ра́дуйся, му́ченичеському ли́ку соприче́тниче;","ра́дуйся, іспові́дником Христо́вим і́стий о́бщниче.","Ра́дуйся, руко́ Боговоди́тельствуємая;","ра́дуйся, льсти́ваго врага́ до́блій одоле́телю.","Ра́дуйся, із'ясни́тельноє Неопи́саннаго писа́ніє;","ра́дуйся, лу́каваго ді́йства посрамле́ніє.","Ра́дуйся, я́ко от стріл зави́стников стра́ждеши;","ра́дуйся, я́ко ті́ми уязвля́єм, пра́вди Бо́жия не отрека́єшися.","Ра́дуйся, я́ко кро́вію вмі́сто черни́л ру́ку твою́ омочи́л єси́;","ра́дуйся, я́ко по ка́зні Бо́жия Ма́тере і Го́спода попече́нію ся пре́дал єси́.","Ра́дуйся, преподо́бне Іоа́нне, Це́ркве учи́телю сладкогла́сний і прему́дрий."]},{"h":"Кондак 5","ps":["Боготе́чния звізди́ сла́ву подража́ющи, яви́ся десни́ця твоя́, Іоа́нне Богоно́се, я́ко волхво́м, указу́ющая лю́дем, ка́ко мо́гуть поклоне́ніє пра́во принести́ Бо́гові, во о́бразі у́бо зря́ще Су́щаго, в пі́нії же Тому́ пою́ще: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́ді Пречи́стая Влади́чиця Іоа́нна припа́дающа ко о́бразу Єя́, в болі́зні стеня́ща, усіче́нную десни́цю прилага́юща, і по ві́рі своє́й на Єя́ по́мощ упова́юща: вся бо соді́яти мо́жеть, я́ко Ма́ти Бо́жия, хотя́щи. Яви́ся же єму́ во сні Пречи́стая, приє́млющи обі́т того́, писа́ньми не преста́ти восхваля́я Бо́га і Богороди́тельницю, і се ісціле́ніє удо́б дарова́ руці́ ві́рнаго, єму́же ми возопії́м:","Ра́дуйся, благогові́йний к Бо́гу моле́бниче;","ра́дуйся, Богоро́диці Пречи́стия дерзнове́нний бесе́дниче.","Ра́дуйся, я́ко во у́шію Єя́ бисть моли́тва твоя́;","ра́дуйся, я́ко внят Хода́тайце вседержа́вний Син Єя́.","Ра́дуйся, всемо́щнаго покро́ва Богома́тере ликова́ніє;","ра́дуйся, неістощи́мия благода́ті небе́сния прия́телище.","Ра́дуйся, непосра́мленноє упова́ніє на Го́спода;","ра́дуйся, цільби́ небе́сния і нам ни́ні проше́ніє.","Ра́дуйся, чудесе́ Бо́жия свиді́телю;","ра́дуйся, оглаго́ланних, в болі́зніх су́щих і в муче́ніїх прия́телю.","Ра́дуйся, я́ко Всемогу́щаго Врача́ лека́рство улучи́л єси́;","ра́дуйся, я́ко Тому́, во ві́рі па́ки укрі́плься, всім живото́м послужи́л єси́.","Ра́дуйся, преподо́бне Іоа́нне, Це́ркве учи́телю сладкогла́сний і прему́дрий."]},{"h":"Кондак 6","ps":["Пропові́да покланя́ємаго тобо́ю Бо́га чу́до ісціле́нія твоєго́ пред царе́м сараци́нським: го́ре мні, проглаго́лати у́бо увеща́вшеє, непра́веднаго же буєсло́вія того́ пода́вше разумі́ніє. Ти же, Іоа́нне Богоблаже́нне, воспі́л єси́ десни́ці Ви́шняго Боже́ственную си́лу: Аллилу́я."]},{"h":"Ікос 6","ps":["Сія́ніє святи́ні твоєя́ яви́ся пред царя́ Дама́ськаго, не удержа́ бо ле́сти власть на се́рдці неві́рнаго власти́теля власти́тель ле́сти, о Іоа́нні пра́ведне. Честь же са́на хотя́ ті возврати́ти і вла́сті полноту́, усли́ша тя князь, к ногу́ єго́ припа́д прося́ща, да пусти́ть тя, по Го́споді іти́ мона́хом. Єда́ у́бо о сем смире́нії не воспої́м ізбра́ннаго Христо́ва си́це:","Ра́дуйся, пра́веднаго житія́ оправда́ніє;","ра́дуйся, преподо́бнаго жи́тельства жела́ніє.","Ра́дуйся, Богома́терняго чудесе́ соприча́стниче;","ра́дуйся, Христо́ви і́стини із'ясни́телю.","Ра́дуйся, срамля́ющим я́же о Христі́ оби́димия срамле́ніє;","ра́дуйся, благословля́ющим я́же о Бо́зі благотворя́щия благослове́ніє.","Ра́дуйся, Бо́жия чудесе́ явле́ніє;","ра́дуйся, я́ко яви́лся єси́ Богоневі́стния Ма́тере благоволе́ніє.","Ра́дуйся, і́ночеськаго житія́ ча́ятелю;","ра́дуйся, кра́сних земни́х, лю́бве ра́ди Бо́жия, отрева́телю.","Ра́дуйся, собла́зну не імі́вий мі́ста в се́рдці твоє́м;","ра́дуйся, я́ко о́но то́чію любве́ і кро́тости іспо́лнил єси́.","Ра́дуйся, преподо́бне Іоа́нне, Це́ркве учи́телю сладкогла́сний і прему́дрий."]},{"h":"Кондак 7","ps":["Хотя́щу ті пра́во возда́ти сло́во Бо́гові і в нищету́ смире́нія облещи́ся, ра́бе благи́й Христо́в, раби́ твоя́ пусти́л і вся імі́нія разда́л єси́, в рабо́ту мона́ха предложи́тися грядя́. Тім у́бо во оби́тель прише́дий свята́го Са́вви, ігу́меном прия́т бисть, хвале́бная воспі́л єси́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вих подвиго́в риста́лище себі́ стяжа́л єси́, Іоа́нне во́їне Христо́в, єди́на ста́рця во учи́теля приє́м, я́ко да смире́нію научи́ть тя і послуша́нію: се да не пре́ждніх чесо́ твори́л би, а́ще і благи́х, по твоє́й во́лі, но во́ля ста́рця, і безмо́лвіє, і се́рдця чистота́, і труд рабо́тен тебі́ во о́браз битія́ вміни́шася: сего́ ра́ди восхваля́єм тя, блаже́нне Іоа́нне:","Ра́дуйся, фимія́ме доброді́тельнаго жи́тельства;","ра́дуйся, о грісі́х пре́жнія жи́зні слез проли́тіє.","Ра́дуйся, тіле́сними труди́ украше́йся;","ра́дуйся, духо́вними по́двиги преображе́йся.","Ра́дуйся, Богогла́сная трубо́, смире́нія ра́ди умолча́вшая;","ра́дуйся, я́ко писа́ло отложи́вий є́же ізбі́гнути превозноше́нія ми́сленнаго.","Ра́дуйся, тіле́сно здрав, ду́шу уврачева́ти прише́дий;","ра́дуйся, обоя́ от Творця́ приє́мий.","Ра́дуйся, висото́ смиренному́дрія;","ра́дуйся, красото́ Христо́ва подража́нія.","Ра́дуйся, прекосло́вія і ро́пота в се́рдці твоє́м не позна́вий;","ра́дуйся, змі́я гні́ва і сумні́нія із по́мисл твої́х ізгна́вий.","Ра́дуйся, преподо́бне Іоа́нне, Це́ркве учи́телю сладкогла́сний і прему́дрий."]},{"h":"Кондак 8","ps":["Стра́нноє і А́нгелом, і челові́ком бисть ви́діти тя, Іоа́нне Богоно́се, во гра́ді би́вшия твоєя́ сла́ви вре́тищем оболче́ннаго, по послуша́нію ко́шници прости́я ціно́ю преви́шшею і́щуща прода́ти: оба́че о таці́м небре́г уничиже́нії, помо́гшаго ті Бо́га благослове́ніє духо́внаго отця́ іспо́лнити хваля́ просла́вил єси́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бив го́рніх іспо́лнь, Іоа́нне Богослове́сниче, обрі́лся єси́ от ста́рця облича́єм, а́ки Ада́м преслуша́нієм подпа́д рая́ отлуче́нію, в до́льних хоті́ніє вміни́ бо той о єди́нім бра́те заупоко́йноє твоє́ пі́ніє, є́же умоле́н бив сотвори́л бі ти: ми же ві́руя днесь ті во усла́ді ра́йстій би́ти, поє́м ті сла́вная:","Ра́дуйся, се́рдце іми́й состра́ждущеє;","ра́дуйся, вні́мляй слізе́ прося́щаго.","Ра́дуйся, поя́й сла́ву ко Христу́ отше́дших;","ра́дуйся, услажда́яй живи́х о ра́дости небе́с дости́гших.","Ра́дуйся, покая́нія пред сме́ртію моли́тву в пі́сні проли́ти науча́яй;","ра́дуйся, вся тлі́нная гріхо́вная пред срі́тенієм Го́спода оста́вити взива́яй.","Ра́дуйся, оста́вил бо єси́ висо́кая земна́я;","ра́дуйся, наслі́дил бо єси́ сих ра́ди преви́спренняя небе́сная.","Ра́дуйся, послуша́нія вся́каго ісполне́ніє на ся взе́мий;","ра́дуйся, в преслуша́нії покая́ніє ді́тельноє яви́вий.","Ра́дуйся, я́ко, гріха́ ра́ди ісправле́нія, гну́са не возгнуша́лся єси́;","ра́дуйся, я́ко іску́са ра́ди неудобоприя́тная претерпі́л єси́.","Ра́дуйся, преподо́бне Іоа́нне, Це́ркве учи́телю сладкогла́сний і прему́дрий."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ би ізнемо́гло наложе́ннаго на тя, Іоа́нне смиреннолю́бче, преще́нія, а́ще і мона́шеськими украше́но: но твоє́ зря ста́рець на унічиже́нія благоприя́тіє, ті спребива́юща воспі́ смире́нна се́рдцем і кро́ткаго Христа́: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́й глагололю́бних пра́здно яви́ся сло́во, благовеща́нна мудролю́бця Іоа́нна тща́щеся воспі́ти доброді́тель: не у́бо той своє́ю во́лею, но во́лею Пречи́стия Влади́чиці, ко ста́рцю єго́ я́вльшіяся, откри́ уста́ своя́, Госпо́дь же та іспо́лни Ду́ха. Да помо́жеть Сей і нам, блаже́нне, тебі́ воспі́ти:","Ра́дуйся, вся́кия пло́ті ра́дость о Богоро́диці воспі́вий;","ра́дуйся, я́ко велі́нієм Пренепоро́чния із устну́ твоє́ю то́ки Богосло́вія ізлія́шася.","Ра́дуйся, общежи́тельнаго житія́ согла́сіє;","ра́дуйся, мона́шеськую мни́вий ке́ллію я́ко рая́ блаже́нство.","Ра́дуйся, неіжди́вноє ангелопо́добноє пі́ніє;","ра́дуйся, я́ко до ни́ні преподо́бними гла́си твої́ми Бо́га воспіва́єши.","Ра́дуйся, сла́ву обріти́й в безсла́вії земні́м;","ра́дуйся, собла́зна ізбеги́й во вели́чіїх до́льних.","Ра́дуйся, о Цари́ Бо́зі раба́ себі́ соді́явий;","ра́дуйся, ра́бство земни́я вла́сті презрі́вий.","Ра́дуйся, є́же сла́вити Бо́га ме́де усто́м на́шим;","ра́дуйся, Богосло́вія необину́ємаго златослове́сниче.","Ра́дуйся, преподо́бне Іоа́нне, Це́ркве учи́телю сладкогла́сний і прему́дрий."]},{"h":"Кондак 10","ps":["Спасе́нія лю́дем хотя́щаго Бо́га просла́вил єси́, достоблаже́нне Іоа́нне Богоревни́телю, да не ка́ко ра́зуми отве́ргнуться Творця́, у́мно челові́ки призива́яй пі́ти і́же гріха́ жа́ло сме́ртноє от челові́к От'є́мшаго: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіни́ церко́вния часть бив, святи́й уго́дниче Дамаски́не, твоєя́ душі́ врагу́ не дал єси́, ні лю́ди церко́вния растли́ти словеси́ бла́зними: не ізмишле́ній ба́сни рек, но посіще́нія сподо́блься Ду́ха Бо́жия, віща́л єси́, о Іоа́нні, Боже́ственная оправда́нія, о ни́хже си́це благода́рственні ті воспису́єм:","Ра́дуйся, Бо́га созерца́ющеє се́рдце;","ра́дуйся, духоначерта́нноє писа́ніє.","Ра́дуйся, на ми́сленний Сина́й Боговиді́нія возше́дий;","ра́дуйся, із глубини́ смире́нія на церко́вную го́ру святи́ні вознеси́йся.","Ра́дуйся, святи́телей тве́рдоє Богоми́сліє;","ра́дуйся, преподо́бних тишино́ смиренному́драя.","Ра́дуйся, ієре́єм свяще́нния та́йни із'ясне́ніє;","ра́дуйся, ніже́ кому́ і́стину затворе́й сла́дости Богопозна́нія.","Ра́дуйся, возлюби́вий не обину́яся послі́довати пра́вді;","ра́дуйся, із ке́ллії воздержа́нія ізрасти́вий плодобога́тство в духо́вних ча́діх.","Ра́дуйся, світи́льниче сві́та пребоже́ственнаго;","ра́дуйся, ма́нтією і́ночеською погреби́й ми́ра сла́ву бре́нную.","Ра́дуйся, преподо́бне Іоа́нне, Це́ркве учи́телю сладкогла́сний і прему́дрий."]},{"h":"Кондак 11","ps":["Пою́щим нам словеса́ тобо́ю воспе́тая, благи́й Христо́в учениче́ Іоа́нне, ісчи́слити я не могу́ще, не то́щих тщі́мся подража́ти глаго́лов мно́жество, но увіре́нія Боже́ственнаго си́лу зря́ще в словесі́х твої́х, не премолчи́м в тебі́ Свята́го Ду́ха ді́йствія, глаго́люще: Аллилу́я."]},{"h":"Ікос 11","ps":["Світосія́нную наде́жду живота́ ві́чнаго в творе́нія твоя́ вдохну́л єси́: всім і́же погребсти́ іму́щим, є́же о нас показа́л єси́ расторже́нія соу́за Богосочета́ннаго душ і тіле́с та́їнство, оба́че блаже́нства нестаре́ющагося обітова́ніє і во кро́віх праведни́х вселе́нія наде́жду слове́сні ізобразу́я; в тебі́ же ви́дим, блаже́нне Іоа́нне Дамаски́не, по преставле́нії твоє́м, я́ко дово́льні послу́жившу Бо́гові, сих свято́є восприя́тіє: ті́мже, а́ще і ску́дную, прийми́ от нас піснь сію́:","Ра́дуйся, у гро́ба пла́чующия утіша́яй;","ра́дуйся, глаго́ли усо́пших нам пі́сненно віща́яй.","Ра́дуйся, о гряду́щих ко Го́споду моли́твенні воздиха́яй;","ра́дуйся, срі́теніє преста́вльшихся со Христо́м предобража́яй.","Ра́дуйся, слове́снаго врачева́нія нача́льниче;","ра́дуйся, догмати́чеськаго наказа́нія ресното́.","Ра́дуйся, бу́дущия жи́зні в го́рніх яснозри́телю;","ра́дуйся, о в нераска́янних грісі́х печа́лі повествова́телю.","Ра́дуйся, пі́сньми твої́ми сме́рті страх упрежда́яй;","ра́дуйся, стра́ха Бо́жия утвержде́нію науча́яй.","Ра́дуйся, десни́це, крі́постію писа́ній благолі́пно просла́вленная;","ра́дуйся, ра́зуме, просвіща́яй конці́.","Ра́дуйся, преподо́бне Іоа́нне, Це́ркве учи́телю сладкогла́сний і прему́дрий."]},{"h":"Кондак 12","ps":["Благода́ті Да́теля во́льно восприя́л єси́ ра́зумом і се́рдцем, я́ко сий раб Госпо́день, ра́бства, Іоа́нне, мни́маго не убоя́лся єси́, лука́вия рабо́ти отве́ргий сою́з, побі́дно восклиця́я: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м воспі́вшаго го́рніх сла́ву, Іоа́нна всебога́таго: того́ дивля́ємся благоплодоно́сію, о́браза уче́нія і му́дрости висоти́, смире́нія же тишини́ велегла́сния, яви́ся бо вселе́нній правосла́вноє ісправле́ніє і дре́вніх христолю́бцев ко́рень, єму́ же уста́ на́ша да не закосне́ють пі́ти:","Ра́дуйся, духо́внаго наслі́дія сокро́вище;","ра́дуйся, млека́ слове́снаго о спасе́нії ізоби́льноє істоче́ніє.","Ра́дуйся, на землі́ воспі́вий, а́ки а́нгелов лик, сла́ву Христо́ва воскресе́нія;","ра́дуйся, славосло́в'яй ни́ні Го́спода у Престо́ла Того́ на небесі́х.","Ра́дуйся, Бо́жия Ма́тере слове́сная похвало́;","ра́дуйся, Ца́рствія небе́снаго живописа́телю.","Ра́дуйся, смоко́вниці, плод твой во вре́м'я своє́ преізоби́льно да́вшая;","ра́дуйся, услади́вшеє смо́кви слове́с твої́х благокоре́нноє дре́во Христо́ви ві́ри.","Ра́дуйся, цві́те благоуха́яй і́стиною;","ра́дуйся, єреті́чеськаго злово́нія істощи́телю.","Ра́дуйся, сла́ви Бо́жия многопло́дноє писа́ніє;","ра́дуйся, ві́ри Христо́ви неіждива́ємоє уче́ніє.","Ра́дуйся, преподо́бне Іоа́нне, Це́ркве учи́телю сладкогла́сний і прему́дрий."]},{"h":"Кондак 13","ps":["О вели́кий песносло́вче Іоа́нне Дамаски́не, ві́ри Христо́ви до́бльственний ра́тниче і учи́телю, велича́яй на землі́ го́рніх Боже́ственную сла́ву, і до́льних науча́яй сми́сли і́стини: да не бу́дуть тщи тебі́ моли́тви на́ша: услади́ нас поуче́нії твої́ми, і небе́сним засту́пничеством огради́ нас, да небла́зненно со святи́нею твоє́ю Вели́каго поє́м і велича́єм Бо́га: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Ангелонра́вноє житіє́ предпоче́т, Іоа́нне благознамени́ті, прине́сл єси́ же́ртву Христу́ великосано́вния жи́зні отрече́нія, си́це і от му́дрости челові́чі поче́рп, найпа́че возлюби́л єси́ Бо́жия прему́дрости сла́дость, і в пусти́ні смире́нно все́лься, із'ясни́л єси́ пра́вия ві́ри висо́т простоту́. Сего́ ра́ди я́ко Боже́ственних уче́ній істо́чнику взива́єм ті:","Ра́дуйся, світи́льниче Боже́ственнаго сві́та, сія́яй в нощі́ неві́рія;","ра́дуйся, побо́рниче і́стинния ві́ри, умудря́яй словеси́ Богопозна́нія.","Ра́дуйся, благознамени́таго ро́да о́трасле;","ра́дуйся, смиренному́драго преподо́бія о́бразе.","Ра́дуйся, процві́тшая во среді́ ага́рян христия́нськая похвало́;","ра́дуйся, во тщесла́внем ми́рі прозя́бшеє кро́тости Христо́ви преподо́біє.","Ра́дуйся, от филосо́фов ми́ра науче́нний;","ра́дуйся, от Прему́дрости Бо́жия умудре́нний.","Ра́дуйся, я́ко возда́л єси́ Бо́жиє Бо́гові;","ра́дуйся, я́ко презрі́л єси́ кра́сная ца́рськая.","Ра́дуйся, благода́ті Бо́жия тезоімені́те;","ра́дуйся, Ца́рства ві́чнаго наслі́дниче.","Ра́дуйся, преподо́бне Іоа́нне, Це́ркве учи́телю сладкогла́сний і прему́дрий."]},{"h":"Кондак 1","ps":["Ізбра́ннаго сосу́да благода́ті Бо́жия, Іоа́нна Богохва́льнаго, притеце́м всі восхвали́ти, от Дама́ська у́бо гра́да звізду́ всесві́тло возше́дшую, Вселе́нськия же Це́ркве свирі́ль приснопою́щую Боже́ственних та́їн і́стину, пренебре́гшаго сла́ву ми́ра сла́ви ра́ди Христа́ Бо́га, да вознесе́м єму́ моли́тву ра́дованія:","Ра́дуйся, преподо́бне Іоа́нне, Це́ркве учи́телю сладкогла́сний і прему́дрий."]},{"h":"Молитва 1-а","ps":["О преподо́бне свяще́нне Іоа́нне Богосла́вний, Дама́скова похвало́, вселе́нния правосла́вная велеле́пото: к тебі́ тече́м, к тебі́ мо́лимся, Боже́ственний Дамаски́не: не преста́й про́чеє моля́ся ко Пречи́стій Богоро́дице, зане́ у́бо і в житії́ твоє́м земні́м послу́ша тя: найпа́че же ви́ну пребу́ди моли́тва твоя́ о нас ко Го́сподеві Бо́гу на́шему, Єго́же Це́рков ре́вностно, а́ки до́блій ра́тник, от єресе́й і со і́стиннаго путі́ поползнове́нія защити́л єси́. Свя́тче Бо́жий, уго́дниче преблаги́й, ти, я́коже Соломо́н, нічесо́же іспроси́в у Го́спода, ра́зві прему́дрости Бо́жия; ктому́ і смире́нія наказа́нія ничи́мже лише́н бил єси́, і в правле́нії страни́ твоєя́ інові́рния імі́л єси́ часть бога́тую: но тім у́бо па́че показа́лся єси́ і́стинний християни́н, в по́мощі пребива́я убо́гим, оглаго́ланним, о пра́вій ві́рі гони́мим і угнета́ємим. Помози́ нам, Іоа́нне, соблюсти́ся, єда́ ка́ко не отсту́пим чим ма́лим от Христа́ Бо́га на́шего і Єго́ Вселе́нськия Це́ркве: огради́ святи́нею твоє́ю, на́ми ни́ні песносло́вимою, от зломи́слящих нам враго́во ви́димих, найпа́че же от неви́димих духо́в зло́би поднебе́сния. Научи́ ни, свя́те Іоа́нне, оти́шію серде́чному, ра́зума здравоми́слію, во ві́рі несумне́нію, ктому́ же любві́ я́же о Христі́ Ісу́се, є́юже ізря́дне украси́лся єси́, Боже́ственне Дамаски́не. Бу́ди при́сний хода́тай і помо́щник во уче́нії пребива́ющим: умудри́, уцілому́дри, просвіти́ є́же у Престо́ла Бо́жия хода́тайством: с висоти́ го́рнія сла́ви іспроси́ вся, я́же суть поле́зна спасе́нія ча́ющим і о сла́ві Бо́жієй зді, до́лу пеку́щимся. Пода́ждь сло́во бла́го і тве́рдо наста́вником, да Це́ркві ві́рния си́ни воспита́ють, і ча́да досто́йна держа́ві на́шей сотворя́ть. Попеци́ся і о є́же смире́нію і кро́тости се́рдця научи́тися нам, я́коже обоюдоо́стру мечу́, і́мже разсека́ється врага́ челові́чеськаго плете́ніє. Не оста́ви коєго́ждо прося́щаго чесо́ у тебе́ в моли́тві, о благи́х ді́ліх благослови́ і наста́ви, да непреткнове́нно во сла́ву Ца́рства Небе́снаго поживе́м, іді́же со Влади́чицею Богоро́дицею Марі́єю і святи́ми всі́ми, в ни́хже і ти єси́, неізрече́нноє Госпо́днє благослови́ться І́м'я, Отця́, і Си́на, і Свята́го Ду́ха, всегда́, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва 2-а","ps":["Боже́ственне Дамаски́не, о́тче Іоа́нне преподо́бне, небе́снаго наслі́дія учи́телю, па́стирей наста́вителю, глаго́лі я́сний уча́щих і благо́є уча́щихся внима́ніє! Се ми ни́ні сло́во ті хотя́ще моле́бноє рещи́, не оставля́єм притека́ти ко твоє́й святи́ні: о небе́сних бо твоє́ сотвори́л єси́ раче́ніє, живо́т земни́й в жизнь проба́вль ві́чную о Бо́зі. Ті́мже у́бо проше́д путе́м неудобоходи́мим, удо́б нам уготовля́єши в Ца́рствіє Небе́сноє стезі́ во уче́нії твоє́м про́стім, і всеце́лем о Го́споді Ісу́се твоє́м житії́. О Крести́телев соіме́нниче, Христо́вих путе́й сказа́телю і от інохожде́нія духо́внаго во великоми́слії ульще́нних преп'я́тіє, Вседержи́теля умоли́ держа́ву на́шу в ми́рі соблюсти́, от єресе́й і раско́лов ті́ло огради́ти церко́вноє, вла́сті і во́їнства народолю́бни і лю́дем благочести́вим служи́тельни сотвори́ти і враги́ Оте́чествія на́шего вско́рі побіжде́ни соді́яти, ра́зуму же на́шему пода́ти я́сность єва́нгельськую і се́рдцю о любві́ Боже́ственній простоту́. Сий наслі́дія оте́чеськаго часть Дамаски́не, Правосла́вія полноти́ покажи́ ни преє́мники, о вели́кий Іоа́нне, велеле́пото церко́вная! Ті́мже і при конці́ на́шем, а́ще і чим преступи́хом пред святи́нею пра́вди Бо́жия, іспроси́ у Законополо́жника і Всеще́драго Судії́ прости́ти нам я́ко нічесо́же блага́го сотво́ршим, зане́ не ко кому́ бо іно́му в печа́лі іли́ проше́нії припа́дохом, нікому́ же іно́му возвра́щшеся па́ки поклони́хомся, то́чію Христу́ Ісу́су расп'я́тому і воскре́сшему, Си́ну Бо́жию, с Ни́мже і Отцю́ Всеви́шнему, со Ду́хом Єго́ Пресвяти́м, Боже́ственній сей Тро́йце бу́ди сла́ва во ві́ки всеве́чния. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Правосла́вія наста́вниче, / благоче́стія учи́телю і чистоти́, / вселе́нния світи́льниче, / мона́шествующих Богодохнове́нноє удобре́ніє, Іоа́нне прему́дре, / уче́ньми твої́ми вся просвіти́л єси́, цівни́це духо́вная, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Піснопи́сця і честна́го Богоглаго́льника, / Це́ркве наказа́теля і учи́теля, / і враго́в сопротивобо́рця, Іоа́нна воспої́м: / ору́жіє бо взем, Крест Госпо́день, / всю отрази́ єресе́й пре́лесть, / і я́ко те́плий предста́тель к Бо́гу, // всім подає́ть прегріше́ній проще́ніє."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Іоа́нне, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Лаврентію Чернігівському","e":"Akathist to our Venerable Father Laurence of Chernihiv","secs":[{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Бо́жий, преподо́бне о́тче Лавре́нтіє, приє́мий благослове́ніє от Бо́жия Ма́тері і прише́дий во святи́й град Чернигов, є́же всели́тися в оби́тель Пресвяти́я Тро́йці, іді́же ізи́де на тя Дух Святи́й: ізгна́ніє претерпі́вий і мно́жество слове́сних ове́ць себі́ собра́вий, пи́щею сло́ва Бо́жия їх напита́вий і ко Христу́ приведи́й: я́ко імі́я дерзнове́ніє ко Святі́й Тро́йці, не престава́й моля́ся ізба́вити нас от вся́ких бід і скорбе́й, да со умиле́нієм зове́м ті:","Ра́дуйся, преподо́бне о́тче наш Лавре́нтіє, ско́рий помо́щниче і моли́твенниче к тебі́ притека́ющих."]},{"h":"Ікос 1","ps":["А́нгела ди́вна страні́ Черни́говстій яви́ тя Госпо́дь, всея́ тва́рі Соді́тель, я́ко показа́ Ду́ха Свята́го в тя все́льшагося, да́ром прозрі́нія і ісціле́нія обогати́ тя. Ми же, зря́ще тя, сосу́де ізбра́нний Пресвяти́я Богоро́диці, благодаря́ще Бо́га, прославля́єм тя, я́ко світи́льника і моли́твенника на́шего, і прилі́жно зове́м ті сицева́я:","Ра́дуйся, пречу́дний ізбра́нниче Бо́жия Ма́тере;","Ра́дуйся, сосу́де благода́ті преізря́дний.","Ра́дуйся, преподо́бних і святи́телей похвало́ і собесі́дниче.","Ра́дуйся, преподо́бному ста́рцю Серафи́му поревнова́вий.","Ра́дуйся, і по сме́рті с преподо́бними всели́вийся.","Ра́дуйся, я́ко тобо́ю по́мисли нечи́стия облича́ються.","Ра́дуйся, я́ко діла́ блага́я і поле́зная тобо́ю благословля́ються.","Ра́дуйся, преподо́бне о́тче наш Лавре́нтіє, ско́рий помо́щниче і моли́твенниче к тебі́ притека́ющих."]},{"h":"Кондак 2","ps":["Ви́дяще ісполне́ніє боже́ственнаго о лю́діх смотре́нія Отця́ Небе́снаго, ізбра́вшаго от наро́да муже́й пра́ведних ко спаси́тельному служе́нію, ра́ди на́шего поддержанія духо́внаго, і Боже́ственним да́ром прозрі́нія тя наградившаго, вопіє́м Бо́гу в Тро́йці: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Боже́ственний вразуми́ тя, о́тче Лавре́нтіє, єгда́ отре́клся єси́ от жи́зні вре́менния і прите́кл к жи́зні ві́чній, от ю́ности Христа́ прославля́я всім се́рдцем твої́м і Тому́ Єди́ному па́че всіх рабо́тая; прите́кл єси́ в Рихловський монасти́р, та́мо подвиза́яся в пі́нії і чте́нії. Ми же, ви́дяще в тебі́ сосу́д Ду́ха Свята́го, со умиле́нієм зове́м ті си́це:","Ра́дуйся, я́ко от ю́ности пла́менні житіє́ мона́шеськоє возлюби́л єси́;","Ра́дуйся, я́ко от ми́ра сего́ отре́клся єси́.","Ра́дуйся, ста́рость ма́тері упоко́ївий;","Ра́дуйся, по сме́рті тоя́ в оби́телі Святи́теля Никола́я всели́вийся.","Ра́дуйся, я́ко в ме́нших бра́тії та́мо послужи́вий.","Ра́дуйся, я́ко в пі́нії Бо́га в Тро́йці просла́вивий.","Ра́дуйся, я́ко тім Пресвяті́й Богоро́дице угоди́вий.","Ра́дуйся, ра́зумом Боже́ственним люде́й удиви́вий.","Ра́дуйся, преподо́бне о́тче наш Лавре́нтіє, ско́рий помо́щниче і моли́твенниче к тебі́ притека́ющих."]},{"h":"Кондак 3","ps":["Єгда́ усли́ша о тебі́, о́тче Лавре́нтіє, архієпи́скоп Анто́ній, повелі́ приби́ти во град Чернигов, в монасти́р Пресвяти́я Тро́йці; ти же, вне́мля єго́ проше́нію, усилил моли́тви. Тогда́ Сама́ Цари́ця Небе́сная благослови́ тя. Ми же грі́шнії, див'я́щеся сему́ чудеси́, зове́м ко Го́споду: Аллилу́я."]},{"h":"Ікос 3","ps":["Прише́л єси́ во святу́ю оби́тель Пресвяти́я Тро́йці і, узрі́в о́браз Богома́тері Тро́йце-Ільинськия, поклони́лся єму́, я́ко уві́де в нем Я́вльшуюся тебі́ і Повелевшую ідти́ в дом Єя́ Си́на і та́мо просла́вити Єго́. Тогда́ преклони́вся пред Не́ю, проси́л єси́ у Нея́ благослове́нія і покро́ва. Ми же, ви́дяще твоє́ преда́ніє во́лі Бо́жієй, вопіє́м такова́я:","Ра́дуйся, я́ко послуша́ніє ве́ліє Бо́жієй Ма́тері яви́л єси́;","Ра́дуйся, я́ко ізбра́ тя служи́ти Єй во гра́ді Черни́гові.","Ра́дуйся, ди́вним пі́нієм Єя́ просла́вивий;","Ра́дуйся, всего́ себе́ руководству Тоя́ преда́вий.","Ра́дуйся, і до конця́ жи́зні твоє́й Єй до́брі послужи́вий;","Ра́дуйся, в чистоті́ ді́вство твоє́ сохрани́вий;","Ра́дуйся, се́рдцем і уста́ми Єя́ просла́вивий;","Ра́дуйся, о́браз смире́нія нам оста́вивий.","Ра́дуйся, преподо́бне о́тче наш Лавре́нтіє, ско́рий помо́щниче і моли́твенниче к тебі́ притека́ющих."]},{"h":"Кондак 4","ps":["Звізда́ лучеза́рная, озари́вшая путь тебі́, приведе́ тя во святи́й град Ієрусали́м, да поклони́шися Гро́бу Госпо́дню і просла́виши Бо́га, терпевшаго страда́нія за гріхи́ на́ша, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Ви́дя благода́ть і дар Свята́го Ду́ха в тебі́, возлюби́ша тя бра́тія святи́я оби́телі Черні́говськия і ізбра́ша я́ко іску́снаго руководи́теля і жи́знію Бо́гу угожда́юща. Ми же, благодаря́ще тя, вопіє́м тебі́:","Ра́дуйся, Рома́ну сладкопевцю уподо́бивийся.","Ра́дуйся, я́ко с ним в Сіо́ні Го́рнем піснь Бо́гу воспіва́єши.","Ра́дуйся, Царя́ Сла́ви просла́вивий;","Ра́дуйся, на путь спасе́нія нас наста́вивий.","Ра́дуйся, я́ко со А́нгели сла́ву Єго́ воспіва́єши;","Ра́дуйся, пі́нієм свої́м не́бо і зе́млю соєдини́вий.","Ра́дуйся, всіх досто́йно Бо́га сла́в'ящих в біда́х не оставля́єши;","Ра́дуйся, я́ко за них пред Го́сподем і Богоро́дицею хода́тайствуєши.","Ра́дуйся, преподо́бне о́тче наш Лавре́нтіє, ско́рий помо́щниче і моли́твенниче к тебі́ притека́ющих."]},{"h":"Кондак 5","ps":["Вре́м'я наста́, єгда́ попра́на бисть святи́ня, ти же я́ко па́стир до́брий, ду́шу свою́ за о́вці положи́ти гото́вий, не оста́вил єси́ гра́да Черни́гова і оби́телі Тро́йце-Ільинськия, но моли́твами святи́х, под покро́вом Бо́жієй Ма́тері в гора́х Болдиних всели́лся єси́, да та́мо хвале́бную піснь воспіва́єши Бо́гу в Тро́йці єди́ному сла́вимому: Аллилу́я."]},{"h":"Ікос 5","ps":["При́йде час і сбу́деться рече́нноє тобо́ю: обнови́ся Дом Святи́я Тро́йці, в нем же собра́шася вся ча́да твоя́ духо́вная. Ти же в дом Ду́ха Свята́го вшел єси́, боголі́пно єго́ украси́в, і му́дро ста́дом слове́сних ове́ць до кончи́ни твоєя́ руководи́л єси́, і́м'я Бо́жиє призива́ти в ра́достіх і печа́ліх всіх поуча́я, і мно́гим святи́м в труді́х твої́х поревнова́л єси́. Возвраще́ніє моще́й Святи́теля Феодо́сія прови́дів, мі́сто сла́вно єму́ угото́вил. Ми же, хва́ляще Бо́га, да́вшаго тебі́ дух прозрі́нія і ра́зум му́дрий, воспіва́єм піснь такову́ю:","Ра́дуйся, уста́вов церко́вних стро́гий блюсти́телю.","Ра́дуйся, оби́телі многоопитний руководи́телю;","Ра́дуйся, рачи́телю благолі́пія церко́внаго;","Ра́дуйся, Правосла́вія сто́лпе непоколеби́мий.","Ра́дуйся, я́ко мо́щі блаже́ннаго Філаре́та нетлі́нними почита́л єси́;","Ра́дуйся, прише́ствіє Святи́теля Феодо́сія пі́сньми просла́вивий.","Ра́дуйся, пред взо́ром на́шим седьм небе́с начерта́вий;","Ра́дуйся, я́ко і по сме́рті на небесах в ра́йських оби́теліх всели́вийся.","Ра́дуйся, преподо́бне о́тче наш Лавре́нтіє, ско́рий помо́щниче і моли́твенниче к тебі́ притека́ющих."]},{"h":"Кондак 6","ps":["Бу́рю мно́гих бід і скорбе́й жите́йських претерпіва́я, помога́л єси́ всім к тебі́ приходящим; та́ко і по сме́рті не оста́вил єси́ нас грі́шних, запові́дав нам призива́ти тя в ско́рбіх і печа́ліх. Упова́я на моли́твенную по́мощ твою́ пред Го́сподем, вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Прови́дів кончи́ну свою́ ско́рую, о́тче Лавре́нтіє, предре́кл єси́ ю трикра́тно. Ми же мо́лим тя, да не оста́виши нас грі́шних по отше́ствії своє́м, но с на́ми пребу́деши во вся дні, во є́же с ра́достію ублажа́ти тя:","Ра́дуйся, кончи́ну свою́ предуві́дівий;","Ра́дуйся, о ней же мно́гим возвісти́вий.","Ра́дуйся, я́ко ві́чния жи́зні сподо́бивийся.","Ра́дуйся, безболезненним ісхо́дом ду́шу свою́ Бо́гу преда́вий.","Ра́дуйся, я́ко і бі́си в той час вострепета́ша;","Ра́дуйся, сла́дость небе́сную на землі́ вкуси́вий.","Ра́дуйся, я́ко на небесі́ то́ю наслажда́єшися;","Ра́дуйся, я́ко мо́щі твоя́ нетлі́нния нам оста́вил єси́.","Ра́дуйся, преподо́бне о́тче наш Лавре́нтіє, ско́рий помо́щниче і моли́твенниче к тебі́ притека́ющих."]},{"h":"Кондак 7","ps":["Пі́ніє і рида́ніє надгро́бноє ча́да твоя́ духо́вная приноша́ху ті у гро́ба, о́тче Лавре́нтіє, єгда́ преста́вился єси́ ко Го́споду душе́ю: нас же не оста́вил єси́ ті́лом нетлі́нним, пра́веднії бо і по сме́рті жи́ви бу́дуть, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Чети́редесят дній не смолкаше рида́ніє і пі́ніє у гро́ба твоєго́, блаже́нне Лавре́нтіє; ти бо чети́редесят дній ожида́л єси́, єгда́ ча́да твоя́ угото́в'ять ті мі́сто погребе́нія. Пребива́я с на́ми ті́лом во хра́мі, душе́ю же моли́лся єси́ за ни грі́шния пред Господом. Сим пребива́нієм чу́до ве́ліє яви́л єси́: нетлі́нния бо мо́щі твоя́, благово́нія іспо́лненнії, показу́ють свя́тость твою́. Див'я́щеся сему́ чудеси́, восхваля́єм тя та́ко:","Ра́дуйся, благода́ть Бо́жию стяжа́вий;","Ра́дуйся, лозо́ виногра́да Христо́ва.","Ра́дуйся, четиредесятидневним стоя́нієм тілесе́ твоєго́ нас уті́шивий;","Ра́дуйся, я́ко мно́жество чуде́с сотвори́вий.","Ра́дуйся, благоуха́нієм от гро́ба твоєго́ всю оби́тель наполнивий;","Ра́дуйся, я́ко по оконча́нії чети́редесяти дній ті́ло твоє́ с че́стію в гробни́цю положи́ся.","Ра́дуйся, я́ко і до ни́ні нетлі́нно Бо́гом сохрани́ся;","Ра́дуйся, я́ко і по сме́рті нас не оста́вивий.","Ра́дуйся, преподо́бне о́тче наш Лавре́нтіє, ско́рий помо́щниче і моли́твенниче к тебі́ притека́ющих."]},{"h":"Кондак 8","ps":["Пропові́дником і́стини Христо́вой яви́лся єси́, о́тче Лавре́нтіє: непреста́нним служе́нієм Бо́гу і бли́жнім проро́ком дре́внім уподо́бился єси́. Слу́жби Бо́жія в хра́мі соверша́я, в моли́тві келейной неуста́нно подвиза́лся єси́. Тім же і по преставле́нії твоє́м хвале́бную піснь о тебі́ воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Просвіти́ зе́млю Россі́йськую лучеза́рним сві́том ве́ліїм преподо́бний Серафи́м Саро́вський чудотво́рець. По нем лучи́ трисо́лнечнаго сія́нія ізидо́ша от пра́веднаго Іоа́нна, чудотво́рця Кроншта́дтськаго. Ти же, свя́те Лавре́нтіє, но́вий світи́льник по сих яви́лся єси́, просвіща́я і утвержда́я всіх во ві́рі непоколеби́мій. Сего́ ра́ди ті я́ко світи́льнику землі́ Черні́говськия возглаша́єм та́ко:","Ра́дуйся, преподо́бне Лавре́нтіє, ми́ру но́вий світи́льниче;","Ра́дуйся, пред Бо́гом наш но́вий моли́твенниче.","Ра́дуйся, сосу́де злати́й, от чре́ва ма́тері Бо́гом ізбра́нний;","Ра́дуйся, і Богоро́дицею просла́вленний.","Ра́дуйся, служи́телю Христо́в преізря́дний;","Ра́дуйся, я́ко во ієре́єх Тому́ послужи́вий.","Ра́дуйся, я́ко о і́мені твоє́м бі́си падо́ша;","Ра́дуйся, я́ко і́м'я твоє́ А́нгели на небесі́ просла́виша.","Ра́дуйся, преподо́бне о́тче наш Лавре́нтіє, ско́рий помо́щниче і моли́твенниче к тебі́ притека́ющих."]},{"h":"Кондак 9","ps":["Вся́коє сло́во і плоть довлі́ють к похвалі́ твоє́й, о́тче Лавре́нтіє: ти бо дви́жимий Ду́хом Святи́м, от ю́ности і до конця́ дній твої́х сла́вил єси́ і́м'я Всесвята́го Творця́ не́ба і землі́, Єго́ Пречи́стую Ма́тер і всіх святи́х. І по сме́рті с ни́ми водвори́лся єси́ в ра́йських черто́зіх, да і та́мо со всі́ми святи́ми воспіва́єши Бо́гу хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ю богоуго́дна в тебі́ показа́ Госпо́дь, я́ко мно́га ча́да духо́вния к тебі́ ідо́ша. Ві́рнії же Бо́гу да возвеселя́ться с тобо́ю во второ́є прише́ствіє Спаси́теля. Ми же с кро́тостію і смире́нієм приє́млем наставле́нія твоя́ і, подража́я твоєму́ человіколю́бію, с любо́вію воспіва́єм тебі́:","Ра́дуйся, гу́сли ду́ха сладкозвучния;","Ра́дуйся, кимвале восклиця́нія.","Ра́дуйся, цівни́це боговіща́нная;","Ра́дуйся, А́нгелов собесі́дниче.","Ра́дуйся, о Бо́зі жи́ві на́ше подража́ніє;","Ра́дуйся, я́ко наставле́нія твоя́ с ра́достію приє́млем.","Ра́дуйся, я́ко ті́ми муки́ ві́чния ізбавля́ємся;","Ра́дуйся, поуче́ніє от Бо́га нам препода́л єси́.","Ра́дуйся, преподо́бне о́тче наш Лавре́нтіє, ско́рий помо́щниче і моли́твениче к тебі́ притека́ющих."]},{"h":"Кондак 10","ps":["Хотя́ спасти́ ду́шу свою́, всю полноту́ доброді́телей Єва́нгельських в себі́ совокупи́л єси́ богоблаже́нне Лавре́нтіє: апо́стольськоє пропові́даніє, му́ченичеськоє терпі́ніє, преподо́бних воздержа́ніє, нестяжа́ніє, смире́ніє і нищету́ духо́вную. Тім же ни́ні на небесі́, восхваля́юще Христа́ Бо́га, да́вшаго ті крі́пость, помина́й нас, чту́щих сві́тлую па́м'ять твою́, і пою́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Позна́л єси́, богому́дре о́тче Лавре́нтіє, ра́зум Боже́ственних Писа́ній, непреста́нно подвиза́яся в моли́твах, і почерпнул єси́ во́ду живу́, ю́же і нам препода́л єси́; сего́ ра́ди вопії́м ті си́це:","Ра́дуйся, я́ко жа́ждущих от істо́чника Святи́я Тро́йці напая́єши;","Ра́дуйся, ті́ми же вода́ми душі́ ісціля́єши.","Ра́дуйся, вмі́сто пи́щі вода́ми слове́с твої́х нас і ни́ні утіша́єши;","Ра́дуйся, пла́менем слове́с твої́х те́рніє гріхо́в на́ших попаля́єши.","Ра́дуйся, я́ко словеса́ твоя́ па́че ме́да сладча́йша;","Ра́дуйся, я́ко сла́достію слове́с твої́х скорб'я́щим ра́дость да́руєши.","Ра́дуйся, я́ко прореченния тобо́ю словеса́ і ни́ні ісполня́ються;","Ра́дуйся, я́ко в них ми сла́ву твою́ уразумеваєм.","Ра́дуйся, преподо́бне о́тче наш Лавре́нтіє, ско́рий помо́щниче і моли́твенниче к тебі́ притека́ющих."]},{"h":"Кондак 11","ps":["Мно́жество чуде́с соверши́л єси́, о́тче Лавре́нтіє: бі́си ізгна́л і прокаже́нния ісціли́л єси́, падшим духо́вно ру́ку по́мощі твоєя́ просте́рл єси́. Посіти́ і нас в біда́х су́щих, да умиле́нноє пі́ніє тебі́ принося́ще, вопіє́м ди́вному во святи́х Свої́х Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льник сві́та Боже́ственнаго, ти прозорли́во прови́дя гріхи́ на́ша, гнів Бо́жий, пра́ведно на ни дви́жимий, предре́кл єси́. Ми же мо́лим тя, о́тче Лавре́нтіє, я́ко іму́ща дерзнове́ніє пред Го́сподем: іспроси́ нам недосто́йним ми́лость у Бо́га, да я́ко моли́твенника тепла́, ублажа́єм тя, зову́ще:","Ра́дуйся, проро́ком послі́довавий і їм же уподо́бивийся;","Ра́дуйся, пророчествами твої́ми мир наполнивий.","Ра́дуйся, я́ко мно́гим напу́тствіє да́вий;","Ра́дуйся, бу́дущая в їх жи́зні, предсказавий.","Ра́дуйся, я́ко монасти́р по предсказанію твоєму́ устро́їлся;","Ра́дуйся, слове́сних ове́ць па́стирю.","Ра́дуйся, гні́ва Бо́жия на грі́шники возвісти́телю;","Ра́дуйся, покая́нія пропові́дниче і грі́шников ісправи́телю.","Ра́дуйся, преподо́бне о́тче наш Лавре́нтіє, ско́рий помо́щниче і моли́твенниче к тебі́ притека́ющих."]},{"h":"Кондак 12","ps":["Благода́ть ве́лію восхоті́ пода́ти тебі́ Госпо́дь Вседержи́тель, просла́ви тя в житії́ твоє́м, дар прозрі́нія дарова́ тебі́ і мно́жеством чуде́с обогати́. Научи́ і нас воспіва́ти с тобо́ю благода́рственную піснь Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м тя, уго́дниче Христо́в Лавре́нтіє, я́ко ни́зу пребива́я на землі́, удосто́їлся єси́ возви́ситися до висоти́ небе́сния і та́мо возсія́ти ду́хом, я́ко со́лнце, да посіти́ши нас с висо́т небе́сних воспіва́ющих ті сицева́я:","Ра́дуйся, світи́льниче лучеза́рний;","Ра́дуйся, сві́те, мрак бісо́вський разгоня́ющий.","Ра́дуйся, сто́лпе о́гненний і ка́меню непоколеби́мий;","Ра́дуйся, святи́телей люби́мий собесі́дниче.","Ра́дуйся, апо́столов преізря́дний ревни́телю;","Ра́дуйся, му́чеников і преподо́бних сла́во превознесе́нная.","Ра́дуйся, благові́рних похвало́ усе́рдная;","Ра́дуйся, чту́щих па́м'ять твою́ покро́ве і защище́ніє.","Ра́дуйся, преподо́бне о́тче наш Лавре́нтіє, ско́рий помо́щниче і моли́твенниче к тебі́ притека́ющих."]},{"h":"Кондак 13","ps":["О пречу́дний уго́дниче Бо́жий, о́тче наш Лавре́нтіє! Прийми́ сіє́ хвале́бноє пі́ніє, в похвалу́ тебі́ приноси́моє, і твої́м богоприя́тним хода́тайством ізба́ви нас от всіх враг ви́димих і неви́димих, от вся́кия напа́сти і ско́рби, от напра́сния сме́рти і бу́дущия муки́, да сподо́бимся с тобо́ю і со всі́ми святи́ми воспіва́ти Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела ди́вна страні́ Черни́говстій яви́ тя Госпо́дь, всея́ тва́рі Соді́тель, я́ко показа́ Ду́ха Свята́го в тя все́льшагося, да́ром прозрі́нія і ісціле́нія обогати́ тя. Ми же, зря́ще тя, сосу́де ізбра́нний Пресвяти́я Богоро́диці, благодаря́ще Бо́га, прославля́єм тя, я́ко світи́льника і моли́твенника на́шего, і прилі́жно зове́м ті сицева́я:","Ра́дуйся, пречу́дний ізбра́нниче Бо́жия Ма́тере;","Ра́дуйся, сосу́де благода́ті преізря́дний.","Ра́дуйся, преподо́бних і святи́телей похвало́ і собесі́дниче.","Ра́дуйся, преподо́бному ста́рцю Серафи́му поревнова́вий.","Ра́дуйся, і по сме́рті с преподо́бними всели́вийся.","Ра́дуйся, я́ко тобо́ю по́мисли нечи́стия облича́ються.","Ра́дуйся, я́ко діла́ блага́я і поле́зная тобо́ю благословля́ються.","Ра́дуйся, преподо́бне о́тче наш Лавре́нтіє, ско́рий помо́щниче і моли́твенниче к тебі́ притека́ющих."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Бо́жий, преподо́бне о́тче Лавре́нтіє, приє́мий благослове́ніє от Бо́жия Ма́тері і прише́дий во святи́й град Чернигов, є́же всели́тися в оби́тель Пресвяти́я Тро́йці, іді́же ізи́де на тя Дух Святи́й: ізгна́ніє претерпі́вий і мно́жество слове́сних ове́ць себі́ собра́вий, пи́щею сло́ва Бо́жия їх напита́вий і ко Христу́ приведи́й: я́ко імі́я дерзнове́ніє ко Святі́й Тро́йці, не престава́й моля́ся ізба́вити нас от вся́ких бід і скорбе́й, да со умиле́нієм зове́м ті:","Ра́дуйся, преподо́бне о́тче наш Лавре́нтіє, ско́рий помо́щниче і моли́твенниче к тебі́ притека́ющих."]},{"h":"Молитва","ps":["О, всехва́льний о́тче Лавре́нтіє, прийми́ сіє́ ма́лоє моле́ніє, от нас грі́шних тебі́ приноси́моє, і при́зри ми́лостивно с висо́т небе́сних на нас, прося́щих твоєго́ хода́тайства у Престо́ла Пресвяти́я Тро́йці, да пода́сть твої́ми моли́твами мир і благоде́нствіє страні́ на́шей, па́стирем си́лу в моли́тві, і́ноком подкріпле́ніє на путі́ соверше́нства в по́двизіх смире́нія і послуша́нія, вдови́цям і сирота́м заступле́ніє, немощни́м подкріпле́ніє, неду́гующим ду́хом і душе́ю от бісо́в ізбавле́ніє, больни́м ісціле́ніє, путеше́ствующим А́нгела Храни́теля. Всім чту́щим с любо́вію па́м'ять твою́, ві́ру і́скреннюю і непоколеби́мую. І по преставле́нії в жизнь ві́чную приведи́ нас ко Христу́ твої́ми моли́твами, да с тобо́ю прославля́єм Святу́ю Тро́йцю: Отця́ і Си́на і Свята́го Ду́ха, всегда́, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["От ю́ности Христа́ возлюби́л єси́, / і Тому́ ті́сним путе́м послі́дуя, / сосу́д ізбра́н Ду́ха Свята́го бив, / дар чудотворе́нія і прозрі́нія восприї́м: / сего́ ра́ди в невече́рнім сві́те Пресвяти́я Тро́йці при́сно ра́дуяся, / помина́й чад твої́х, // Лавре́нтіє преподо́бне, о́тче наш."]},{"h":"Кондак, глас 4","ps":["Мир оста́вив, чистоту́ а́нгельськую стяжа́в / і ми́рові любо́вію послужи́в, / о́тче наш Лавре́нтіє, / по́мощ благода́тную с ві́рою приходя́щим оби́льно явля́я: / ті́мже і в преми́рная селе́нія досто́йно всели́вся, / ті́лом нетлі́нним с на́ми пребива́єши, / утвержда́я нас в правосла́вній ві́рі отце́в на́ших, / душе́ю світоза́рною Пода́телю ми́ра мо́лишися // дарова́ти нам мир і ве́лію ми́лость."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Лавре́нтіє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобномученику Корнилію Псково-Печерському","e":"Akathist to the Venerable Martyr Cornelius of Pskov-Caves","secs":[{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче, пресла́вний уго́дниче Христо́в, ско́рий помо́щниче і те́плий моли́твенниче о всіх, с ві́рою і любо́вію прося́щих твоєго́ заступле́нія, восхваля́єм тя любо́вію, Корни́ліє преподобному́чениче, ти же я́ко імі́яй дерзнове́ніє ко Го́споду, моли́ о спасе́нії нас, пою́щих ті:","Ра́дуйся, Корни́ліє преподобному́чениче, о́тче наш."]},{"h":"Ікос 1","ps":["А́нгелов подража́тель яви́лся єси́, преподобному́чениче і богоно́сне о́тче наш Корни́ліє, а́нгельськи пожи́вий на землі́ і нам оста́вивий о́браз соверше́нства духо́внаго. Сего́ ра́ди просла́ви тя чудеси́ Христо́с Бог, Єму́же предстої́ши ни́ні во сві́ті невече́рнім Ца́рствія Небе́снаго; от нас же, чту́щих тя, сли́шиши пі́ніє таково́є:","Ра́дуйся, я́ко любве́ ра́ди ко Го́споду вся́коє наслажде́ніє земно́є оста́вил єси́;","Ра́дуйся, я́ко блага́я ми́ра сего́ презрі́л єси́.","Ра́дуйся, я́ко бога́тство нетлі́нноє обрі́л єси́;","Ра́дуйся, я́ко і́го Христо́во благо́є і удобоносимоє возлюби́л єси́.","Ра́дуйся, я́ко во пло́ті а́ки безпло́тен пожи́л єси́;","Ра́дуйся, я́ко боголюбе́зную чистоту́ непоро́чно сохрани́л єси́.","Ра́дуйся, я́ко у́зькими врати́ в Ца́рствіє Небе́сноє вошел єси́;","Ра́дуйся, я́ко равноангельськую честь досто́йно прия́л єси́.","Ра́дуйся, я́ко віне́ць неув'яда́ємий от Го́спода прия́л єси́;","Ра́дуйся, я́ко на небесі́ і на землі́ просла́влен єси́.","Ра́дуйся, Корни́ліє преподобному́чениче, о́тче наш."]},{"h":"Кондак 2","ps":["Ви́дя суєту́ житія́ мирська́го і сли́ша глас Па́стиря Христа́: “І́же а́ще хо́щеть по Мні ідти́, да отве́ржеться себе́ і во́зьметь крест свой”, і ти, преподобному́чениче, мир і вся блага́я єго́ оста́вил єси́, да Єди́ному Бо́гу поживе́ши, поя́ Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом сви́ше просвіще́нний, наста́вил єси́ духо́вная ча́да твоя́ ко благоугожде́нію і́стинному і любе́зно прия́л єси́ вся возжелавшия подвиза́тися ку́пно с тобо́ю во спасе́ніє, о́тче Корни́ліє, спаси́тельнаго путі́ наста́вниче предо́брий; прийми́ у́бо і нас под твой о́тчий покро́в і моли́твами твої́ми помози́ нам спасе́ніє ві́чноє унаслі́довати, да тя восхва́лим си́це:","Ра́дуйся, алчущим і жа́ждущим пра́вди глаго́лов живота́ ві́чнаго возвісти́телю;","Ра́дуйся, іщущим Ца́рствія Бо́жия путі́ спаси́тельнаго указа́телю.","Ра́дуйся, взиску́ющих го́рняго Ца́рствія му́дрий води́телю;","Ра́дуйся, обурева́ємих страстьми́ до́брий ко́рмчий.","Ра́дуйся, во благоче́стії тружда́ющихся вели́кий помо́щниче;","Ра́дуйся, нему́дрих благоїску́сний учи́телю.","Ра́дуйся, те́плий о всем ми́рі предста́телю;","Ра́дуйся, усе́рдний і благоприя́тний о душа́х на́ших хода́таю.","Ра́дуйся, наде́жний кора́бль в жите́йськом пла́ванії обрі́тший;","Ра́дуйся, і нам ти́хую при́стань указа́вий.","Ра́дуйся, Корни́ліє преподобному́чениче, о́тче наш."]},{"h":"Кондак 3","ps":["Си́лою Го́спода умудренний ко благоустроє́нію святи́я оби́телі огради́ти ю от наше́ствія вра́жия стіно́ю, па́че же святи́ми моли́твами твої́ми препоручивий ю честно́му покро́ву Пресвяти́я Богоро́диці, умоли́ да́ти і нам покро́в і защи́ту, да сподо́бимся ку́пно с тобо́ю пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще тя, о́тче Корни́ліє, ско́раго в біда́х помо́щника, благові́рнії лю́діє, в напа́стіх і ско́рбіх тя на по́мощ моли́твенно призива́юще і да́ри бла́гости Бо́жия моли́твами твої́ми от Щедрода́вця Бо́га оби́льно приє́млюще, тебі́ от любве́ те́плия хвале́бно воспіва́ють:","Ра́дуйся, мно́гажди проще́нія на́ша ісполне́нієм предваривий;","Ра́дуйся, боля́щим врачу́ благоїску́сний.","Ра́дуйся, скорб'я́щим благоприя́тноє утіше́ніє;","Ра́дуйся, унивающим благода́тноє укріпле́ніє.","Ра́дуйся, душетлі́нних страсте́й прогони́телю;","Ра́дуйся, безпомо́щним скоропредста́тельний помо́щниче.","Ра́дуйся, і́ноков богому́дрий руководи́телю;","Ра́дуйся, ра́дость і́стинную во Христі́ нам показа́вий.","Ра́дуйся, воєво́до ізря́дний духо́вних во́їнов;","Ра́дуйся, Корни́ліє преподобному́чениче, о́тче наш."]},{"h":"Кондак 4","ps":["Бу́рею страсте́й і треволне́ньми во многом'ятежном ми́рі непоколеби́мий в ти́хоє приста́нище спасе́нія ду́шу твою́ упра́вил єси́, вся блага́я і кра́сная ми́ра презрі́в, призива́я і всіх би́ти прича́стници го́рняго Ца́рствія, іді́же ни́ні пребива́єши, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше па́стиріє Христо́ви Це́ркве о твої́х по́двизіх і я́ко земна́го тя А́нгела помишля́я, ізбра́ша тя во ігу́мена оби́телі, досто́йную по́честь трудо́м твої́м возда́вше і тім подвиза́юще нас благохвали́ти тя си́це:","Ра́дуйся, А́гнця і Па́стиря ві́рний служи́телю;","Ра́дуйся, алтаря Госпо́дня досто́йний предстоя́телю.","Ра́дуйся, богому́дрий і́ноков нача́льниче;","Ра́дуйся, і́стиннаго смире́нія наста́вниче.","Ра́дуйся, богому́дрий і́ноков нача́льниче;","Ра́дуйся, і́стиннаго смире́нія наста́вниче.","Ра́дуйся, соверше́ннаго терпі́нія подви́жниче;","Ра́дуйся, даро́в Свята́го Ду́ха честно́є вмісти́лище.","Ра́дуйся, сле́знаго умиле́нія преіспо́лненний;","Ра́дуйся, Пресвяти́я Тро́йці сосу́де ізбра́нний.","Ра́дуйся, благоче́стія утвержде́ніє;","Ра́дуйся, правосла́вія сто́лпе і похвало́.","Ра́дуйся, Корни́ліє преподобному́чениче, о́тче наш."]},{"h":"Кондак 5","ps":["Боготе́чную мисль соломо́нову імі́я, о́браз Успе́нія Пресвяти́я Богоро́диці написа́ благочести́вий Алексі́й, посліди́ же ра́ди моли́тв преподо́бнаго Корни́лія неізреченниє чудеса́ іко́на явля́ти начаше: ісціля́ше бісни́х, отверзаше о́чі сліпи́м мно́гим, о сем ра́дующеся, і́ноці поя́ху Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Созда́ преподо́бний Корни́лій во ігу́менство своє́ над Святи́ми врата́ми храм Святи́телю Никола́ю Чудотво́рцю, а́ки защи́тнику всіх оби́димих і ревни́телю правосла́вія, упова́я би́ти єму́ храни́телю оби́телі от враго́в правосла́вія; ті́мже і ни́ні с ним предстоя́ Престо́лу Го́спода Сла́ви, помоли́ся, о́тче Корни́ліє, Творцю́ о спасе́нії всіх потруди́вшихся ра́ди святи́я оби́телі і о всіх сла́в'ящих тя пі́ньми сицеви́ми:","Ра́дуйся, пра́вило ві́ри і благоче́стія;","Ра́дуйся, о́бразе цілому́дрія і воздержа́нія.","Ра́дуйся, по́стничеськаго ли́ка украше́ніє;","Ра́дуйся, звіздо́, сія́ющая в со́нмі преподо́бних.","Ра́дуйся, і́ноков па́стирю і учи́телю;","Ра́дуйся, і в ми́рі живу́щих засту́пниче і покрови́телю.","Ра́дуйся, ті́сний і приско́рбний путь па́че простра́ннаго возлюби́вий;","Ра́дуйся, учи́телю му́жественнаго подви́жничества.","Ра́дуйся, стіно́, неви́димо огражда́ющая па́че стін ка́менних;","Ра́дуйся, же́ртва вече́рняя Бо́гу прия́тная.","Ра́дуйся, Корни́ліє преподобному́чениче, о́тче наш."]},{"h":"Кондак 6","ps":["Пропові́дуя сло́во Бо́жиє бра́тії твоє́й, всіх поуча́л єси́ сло́вом і житіє́м безмо́лвію, смире́нію, посту́ і моли́тві, в не́йже денноно́щно пребива́я, воспіва́л єси́ ви́ну Всеси́льному Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ світи́льник ві́ри, о́тче Корни́ліє, оби́телі твоє́й та́кожде і окре́стним лю́дем, зе́млю же Ливо́нськую ві́рою християнською просвіти́л єси́, неви́димий храм Ду́ха Бо́жія в себі́ нося́, устро́їл єси́ ви́димий храм Пречи́стия Богоро́диці Одиги́трії і новопросвіще́нній чуди хра́ми основа́л єси́, та́кожде і кли́рики устро́їл єси́, да всі обря́щуть врачева́ніє неду́г свої́х душе́вних. Сего́ ра́ди просла́влен єси́ от Подвигополо́жника Христа́, от нас же приє́млеши сія́ похва́льния пі́сні:","Ра́дуйся, Єва́нгелія Христо́ва благовестителю;","Ра́дуйся, ві́ри правосла́вния пропові́дниче.","Ра́дуйся, благода́тію Бо́жиєю насище́нний;","Ра́дуйся, от істо́чника Боже́ственнаго напоє́нний.","Ра́дуйся, пото́ком слез спаси́тельних орошенний;","Ра́дуйся, в ри́зу спасе́нія облече́нний.","Ра́дуйся, оде́ждою нетлі́нія оді́янний;","Ра́дуйся, бра́шно неісчерпа́ємоє указа́вий.","Ра́дуйся, питіє́ приснотеку́щеє Христа́ пропові́давий;","Ра́дуйся, манной сло́ва Бо́жия лю́ди пита́вий.","Ра́дуйся, Корни́ліє преподобному́чениче, о́тче наш."]},{"h":"Кондак 7","ps":["А́гнцю Бо́жию, взе́мшему гріхи́ ми́ра, подража́я, кро́тость і смире́ніє Єго́ себі́ усво́їл єси́, о́тче Корни́ліє, і ві́янія ско́рби і оби́ди безро́потно претерпі́л єси́, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вния і до́блестния по́двиги твоя́ восхваля́юще, добропобедне во́їне Христо́в Корни́ліє, ублажа́єм тя, от тлі́ннаго сего́ житія́ земни́м царе́м к Небе́сному Царю́ во ві́чноє жили́ще предпосланнаго, сла́вим му́ченичеськую кончи́ну твою́ і моли́твенно пра́зднуєм святу́ю па́м'ять твою́, тебі́ усе́рдно воспіва́юще:","Ра́дуйся, я́ко невинною кро́вію твоє́ю чи́стоє житіє́ запечатлі́л єси́;","Ра́дуйся, я́ко в час сме́ртний к ли́ку Му́чеников причислен єси́.","Ра́дуйся, я́ко отверзо́шася ті врата́ ра́йськая, да вни́деши в ра́дость Го́спода твоєго́;","Ра́дуйся, я́ко ду́шу твою́ Жизнода́вець Христо́с в селе́нія небе́сния прия́л єси́.","Ра́дуйся, я́ко мо́щі твоя́ на землі́ просла́вишася;","Ра́дуйся, я́ко со безпло́тними си́лами трисвяту́ю піснь Бо́гу немо́лчно воспіва́єши.","Ра́дуйся, я́ко с Проро́ки і Апо́столи сві́тло торжеству́єши;","Ра́дуйся, со святи́ми Му́ченики ку́пно увінча́нний.","Ра́дуйся, с Преподо́бними і праведниками просла́вленний;","Ра́дуйся, Корни́ліє преподобному́чениче, о́тче наш."]},{"h":"Кондак 8","ps":["Странника і прише́льця в ми́рі сем себі́ помишля́я і го́рняго Ієрусали́ма взиску́я, тече́ніє вре́менния жи́зні во святі́й оби́телі Бо́жия Ма́тере сконча́л єси́, Є́йже і ни́ні предстої́ши о сем моля́ся, да всі ку́пно с тобо́ю пою́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Побіди́во вся враги́ ору́жієм пра́вди Бо́жия, я́ко і́стинний во́їн Христо́в увенчен вінце́м побі́дним в Ца́рстві сла́ви, іді́же пребива́я с преподо́бними Ма́рком і Іо́ною, і ни́ні огражда́єши от враго́в оби́тель твою́, призива́я і нас подража́ти ті в духо́вній бра́ні, да і ми в ра́дості духо́вній вопіє́м ті:","Ра́дуйся, смире́нієм святи́м горди́ню в себі́ побіди́вий;","Ра́дуйся, кро́тостію соверше́нною я́рости пла́мень угаси́вий.","Ра́дуйся, моли́твами усе́рдними уни́ніє ду́ха прогна́вий;","Ра́дуйся, ра́дованія о Го́споді дости́гнувий.","Ра́дуйся, воздержа́нієм і цілому́дрієм чистоту́ душі́ і ті́ла соблю́дший;","Ра́дуйся, нелі́ностно вся́ку доброді́тель в себі́ возрасти́вий.","Ра́дуйся, віне́ць побі́дний от Христа́ прия́вий;","Ра́дуйся, от Го́спода да́ром чуде́с обогащенний.","Ра́дуйся, в лик добропобі́дних Му́ченик прия́тий;","Ра́дуйся, а́ки до́брий во́їн к во́їном небе́сним сопричтенний.","Ра́дуйся, Корни́ліє преподобному́чениче, о́тче наш."]},{"h":"Кондак 9","ps":["Вся́коє наслажде́ніє плотсько́є возненави́дів, Корни́ліє преблаже́нне, єди́наго Бо́га всім се́рдцем возлюби́л єси́ я́ко істо́чника вся́кия бла́гости, ті́мже і Госпо́дь тя возлюби́ і оби́льно щедро́ти Своя́ на тя і оби́тель твою́ ізлія́, да всі к моще́м твої́м прибіга́ющії і ско́рую по́мощ от тебе́ приє́млющи благода́рственно вопію́ть: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії не довлі́ють глаго́лати вся по́двиги твоя́, богому́дре о́тче Корни́ліє, і́бо добро́та житія́ твоєго́ воі́стину превосхо́дить похвалу́ челові́чеськую, оба́че ми любо́вію к тебі́ побужда́єми, дерза́єм смире́нно хвали́ти тя пі́нієм такови́м:","Ра́дуйся, святи́я Це́ркве світи́льниче немеркнущий;","Ра́дуйся, всемо́щним заступле́нієм твої́м от меча́ іноплеме́нних нас ізбавля́ющий.","Ра́дуйся, страни́ на́шея благода́тноє украше́ніє;","Ра́дуйся, гра́да на́шего покро́ве благода́тний.","Ра́дуйся, оби́телі твоєя́ утвержде́ніє і похвало́;","Ра́дуйся, мона́шествующих пречу́дная красото́.","Ра́дуйся, ро́ду христия́нському при́сноє утіше́ніє;","Ра́дуйся, лю́б'ящих і чту́щих тя пред Бо́гом хода́таю.","Ра́дуйся, грі́шником ко спасе́нію путі́ указа́телю;","Ра́дуйся, пред Престо́лом Бо́жиїм ми́ру грі́шному предста́телю.","Ра́дуйся, Корни́ліє преподобному́чениче, о́тче наш."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ град Псков і лю́ди правосла́вния от наше́ствія іноплеме́нних, яви́лся єси́ ста́рцю Дорофею ку́пно с Анто́нієм Києвським, сопутствующе Пресвяті́й Богоро́дице, поспешившей на по́мощ лю́дем Свої́м; єгда́ же Богома́тер укоря́юще лю́ди за скве́рну житія́ їх, умоля́л єси́ со слеза́ми, глаго́люще: “О Госпоже́ Влади́чице Богоро́дице, согріши́ша живу́ще беззако́нно, но не оста́ви їх заступле́нієм Твої́м, па́че же моли́ся Си́ну Твоєму́ за лю́ди недосто́йния”, — і та́ко отврати́л єси́ пра́ведний гнів, да зову́ть во умиле́нії Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну заступле́нія і моли́твенника богоприя́тна іму́ще тя, о́тче Корни́ліє, благодаре́ніє Отцю́ Небе́сному усе́рдно возсила́я за вся благодія́нія Єго́, тобо́ю нам оби́льно явля́ємия, тебі́ же, предста́телю на́шему, сицево́є прино́сим пі́ніє:","Ра́дуйся, преди́вний уго́дниче Госпо́день;","Ра́дуйся, неутоми́мий в по́двизіх ізбра́нниче Христо́в.","Ра́дуйся, слуго́ добропослушливий Всеви́шняго Влади́ки;","Ра́дуйся, благи́й і ві́рний ра́бе Царя́ ца́рствующих.","Ра́дуйся, оби́димих до́брий засту́пниче;","Ра́дуйся, стра́нних благонаде́жноє приста́нище.","Ра́дуйся, неду́гов душе́вних і тіле́сних благи́й ціли́телю;","Ра́дуйся, грі́шников пред Бо́гом хода́таю.","Ра́дуйся, ка́ющихся со Христо́м примири́телю;","Ра́дуйся, небе́сний наш покрови́телю.","Ра́дуйся, Корни́ліє преподобному́чениче, о́тче наш."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє не довлі́єть ко прославле́нію вели́чествія твоєго́, о́тче преподо́бне, твої́ми бо моли́твами ди́вно яви́ся си́ла Бо́жия: моли́лся бо єси́ пред пречи́стим о́бразом Влади́чиці і тім оби́тель от разоре́нія сохрани́л єси́. Ни́ні і ми мо́лим тя, не тщу сотвори́ наде́жду на́шу і ізба́ви нас от враг на́ших, да во умиле́нії зове́м Спаси́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льник до́брих діл бил єси́ при жи́зні, о́тче преподо́бне, і світи́льник Бо́жия благода́ті яви́лся єси́ по сме́рті, сія́я чудеси́ і ісціле́нія істоча́я; і по ста дву́десяти лі́тіх, а́ки сокро́вище драгоці́нноє, мо́щі твоя́ із нідр земни́х явле́ни би́ша, да тебі́ от Го́спода просла́вленному уми́льно взива́єм:","Ра́дуйся, нетлі́нія цві́те прекра́сний;","Ра́дуйся, кри́не рая́ небе́снаго процві́тшій.","Ра́дуйся, сві́тлостію твоє́ю мрак душ на́ших озаря́яй;","Ра́дуйся, от болі́зней многоразли́чних благода́тно ісціля́яй.","Ра́дуйся, ран гріхо́вних врачу́ благоїску́сний;","Ра́дуйся, серде́ць скорб'я́щих уті́шителю.","Ра́дуйся, оби́телі твоєя́ стра́же неуси́пний;","Ра́дуйся, спя́щих во грісі́х возбудителю.","Ра́дуйся, бдя́щих в моли́тві укріпи́телю;","Ра́дуйся, Корни́ліє преподобному́чениче, о́тче наш."]},{"h":"Кондак 12","ps":["Благода́ть от Го́спода прия́л єси́, преподобному́чениче, ко просвіще́нію і́ноков і мирськи́х люде́й сві́том і́стинния ві́ри, ті́мже і ученици́ твої́, в земно́м житії́ тобо́ю просвіще́ннії, ни́ні с тобо́ю на небесі́ прославля́ють Вседержи́теля Світода́вця і нас науча́ють славосло́вію, да і ми Творцю́ і святи́х Святі́йшему Сло́ву поє́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ди́вния твоя́ чудеса́, умиле́нно припа́даєм пред пречи́стими моща́ми твої́ми, преподо́бне о́тче наш, благода́рственно воспомина́єм труди́ твоя́ і твоє́ заступле́ніє, і я́коже дре́вле усли́шал єси́ мольби́ рабо́в твої́х, та́кожде і ни́ні усли́ши ско́рбния моли́тви чту́щих тя і сподо́би ни́ні прия́ти ско́роє свобожде́ніє от враго́в спасе́нія на́шего, да невозбра́нно поє́м тебе́ піснь сію́:","Ра́дуйся, всеси́льними моли́твами твої́ми от враго́во ви́димих і неви́димих ізбавля́яй;","Ра́дуйся, сві́том і́стини су́щих во тьмі і сі́ні сме́ртній озаря́яй.","Ра́дуйся, разсла́бленних утвержде́ніє і си́ло;","Ра́дуйся, неві́рних прославля́ти Бо́га науча́яй.","Ра́дуйся, нераска́янних грі́шников к покая́нію обраща́яй;","Ра́дуйся, по́мощ си́рим і вдови́цям подава́яй.","Ра́дуйся, ско́рбних утіша́яй;","Ра́дуйся, в пості́ і моли́твах ослабевающих укріпля́яй.","Ра́дуйся, Корни́ліє преподобному́чениче, о́тче наш."]},{"h":"Кондак 13","ps":["О преподобному́чениче о́тче Корни́ліє, тебі́ мо́лимся і тебі́ про́сим, воньми́ похвальному пі́нію сему́, тебі́ от усе́рдія на́шего приносимому, не оста́ви нас святи́ми твої́ми моли́твами, не преста́ни проси́ти премно́гих гріхо́в на́ших проще́нія, да в сме́ртний час сподо́бимся прия́ти кончи́ну жи́зні ми́рну і вни́ти в Ца́рствіє Небе́сноє, да і ми та́мо с тобо́ю просла́вим безмі́рноє милосе́рдіє Бо́жиє, воспіва́юще Владике живота́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов подража́тель яви́лся єси́, преподобному́чениче і богоно́сне о́тче наш Корни́ліє, а́нгельськи пожи́вий на землі́ і нам оста́вивий о́браз соверше́нства духо́внаго. Сего́ ра́ди просла́ви тя чудеси́ Христо́с Бог, Єму́же предстої́ши ни́ні во сві́ті невече́рнім Ца́рствія Небе́снаго; от нас же, чту́щих тя, сли́шиши пі́ніє таково́є:","Ра́дуйся, я́ко любве́ ра́ди ко Го́споду вся́коє наслажде́ніє земно́є оста́вил єси́;","Ра́дуйся, я́ко блага́я ми́ра сего́ презрі́л єси́.","Ра́дуйся, я́ко бога́тство нетлі́нноє обрі́л єси́;","Ра́дуйся, я́ко і́го Христо́во благо́є і удобоносимоє возлюби́л єси́.","Ра́дуйся, я́ко во пло́ті а́ки безпло́тен пожи́л єси́;","Ра́дуйся, я́ко боголюбе́зную чистоту́ непоро́чно сохрани́л єси́.","Ра́дуйся, я́ко у́зькими врати́ в Ца́рствіє Небе́сноє вошел єси́;","Ра́дуйся, я́ко равноангельськую честь досто́йно прия́л єси́.","Ра́дуйся, я́ко віне́ць неув'яда́ємий от Го́спода прия́л єси́;","Ра́дуйся, я́ко на небесі́ і на землі́ просла́влен єси́.","Ра́дуйся, Корни́ліє преподобному́чениче, о́тче наш."]},{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче, пресла́вний уго́дниче Христо́в, ско́рий помо́щниче і те́плий моли́твенниче о всіх, с ві́рою і любо́вію прося́щих твоєго́ заступле́нія, восхваля́єм тя любо́вію, Корни́ліє преподобному́чениче, ти же я́ко імі́яй дерзнове́ніє ко Го́споду, моли́ о спасе́нії нас, пою́щих ті:","Ра́дуйся, Корни́ліє преподобному́чениче, о́тче наш."]},{"h":"Молитва","ps":["О, святи́й преподобному́чениче Корни́ліє! Смире́нно припа́даєм к ра́ці моще́й твої́х і уми́льно мо́лим тя: ми́лостиво при́зри на ско́рби на́ша душе́вния і тіле́сния і ізба́ву нам пода́ждь; помози́ нам, свя́тче Бо́жий, от наві́та злих челові́к, от ни́хже і сам ти неви́нно на землі́ пострада́л єси́. Защити́ нас от наси́лія дия́вола, стра́стно вою́ющаго в не́мощних удесі́х на́ших, умоли́ Го́спода Бо́га і Пречи́стую Єго́ Ма́тер дарова́ти нам ти́хоє і безгрі́шноє житіє́, взаї́мную бра́тськую нелицемі́рную любо́в і ми́рную христия́нськую кончи́ну, да чи́стою со́вістію предста́нем нелицемі́рному стра́шному суди́лищу Христо́ву, і в Ца́рствії Єго́ просла́вим Животворя́щую Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 6","ps":["Пско́во-Пече́рськая оби́тель, / і́здавна сла́вная чудеси́ іко́ни Богома́терней, / мно́гія і́ноки Бо́гові воспита́, / ту і преподо́бний Корни́лій, / по́двигом до́брим подвиза́ся, / чу́дную Богома́тер сла́в'я, / інові́рния просвіща́я, / і́ноки і мно́гия лю́ди спаса́я, / оби́тель же свою́ ди́вно украша́я і огражда́я. / Ту і му́ченичества віне́ць по мно́гих лі́тіх па́стирства своєго́ до́блестні прия́. / Ті́мже возра́дуємся, лю́діє, Христа́ Бо́га / і Пречи́стую Єго́ Ма́тер возблагодари́м, / я́ко дарова́ нам преподобному́ченика сла́вна // і моли́твенника о душа́х на́ших достоблаже́нна."]},{"h":"Кондак, глас 4","ps":["Сві́тлий світи́льник Правосла́вія / і сугу́бая Пско́вськия землі́ защи́та бил єси́, / многобо́жіє іскореня́я і лю́ди к Бо́гу наставля́я. / Дом Богома́тері тобо́ю укріпи́ся і просла́вися, / доброді́тельми же укра́шен, віне́ць му́ченика прия́л єси́, // помина́й нас, чад твої́х, і у Го́спода, преподобному́чениче Корни́ліє."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподобному́чениче Корни́ліє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст великомученику Феодору Стратилату","e":"Akathist to the Great Martyr Theodore Stratelates","secs":[{"h":"Кондак 1","ps":["Возбра́нному воєво́ді і сла́вному во страда́льціх во́їну, свято́му великому́ченику Фео́дору, прийді́те піснь хвале́бную вку́пі воспої́м. Ти же, великому́чениче, я́ко імі́я дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, святи́й великому́чениче Фео́доре, Вели́кий Стратила́те."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і всея́ тва́рі Созда́тель яви́ тя Це́ркві Своє́й, я́ко страда́льця до́блественна і во́їна непобіди́ма, да всі по достоя́нію страда́нія твоя́ восхва́лять, страстоте́рпче Фео́доре. Сего́ ра́ди і ми, я́ко му́ченика днесь чту́ще, восхваля́єм ті, вопію́ще:","Ра́дуйся, і́дольськаго служе́нія пре́лесть обличи́вий.","Ра́дуйся, я́рость безу́мнаго царя́ язи́чеськаго презрі́вий.","Ра́дуйся, сего́ ра́ди муче́нія ве́лія і ра́ни сме́ртния претерпі́вий.","Ра́дуйся, я́ко Христо́с от Пила́та, от Лики́нія царя́ пло́тію на кресті́ пригвожде́нний.","Ра́дуйся, от А́нгела Госпо́дня па́ки живо́т і крі́пость ди́вно восприя́вий.","Ра́дуйся, с ра́достію о Го́споді главу́ свою́ честну́ю под меч преклони́вий.","Ра́дуйся, святи́й великому́чениче Фео́доре, Вели́кий Стратила́те."]},{"h":"Кондак 2","ps":["Зря́ще страда́льця до́блественна і во́їна непобіди́ма свята́го великому́ченика Фео́дора, страда́ньми вінці́ побі́дния прия́вша і со А́нгели сочета́вшася і чуде́с сокро́вище ми́ру дарова́вша, ві́рнії єдиному́дренне почти́м, воспіва́юща Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум боже́ственний стяжа́в, змі́я ве́лія і стра́шна, близ Євхаї́тська гра́да вогнезди́вшася, кресто́м і мече́м порази́л єси́, во́їне Христо́в, ті́мже і стратила́ть, єси́ воєво́да, возста́влен бі на землі́. Ми же я́ко небе́сному воєво́ді вопіє́м ті:","Ра́дуйся, си́лою Христо́вою от змі́я того́ лю́таго оте́чество своє́ свободи́вий.","Ра́дуйся, мно́гоє наро́да мно́жество ко Христу́ обрати́вий.","Ра́дуйся, ору́жієм ві́ри де́монов полки́ побіди́вий.","Ра́дуйся, я́ко побідоно́сний яви́лся єси́ на землі́ страда́лець.","Ра́дуйся, чуде́с мно́жество с ві́рою к тебі́ прибега́ющим подава́яй.","Ра́дуйся, Христу́ Бо́гу моли́тися за ни ми́лостиво не оскудіва́яй.","Ра́дуйся, святи́й великому́чениче Фео́доре, Вели́кий Стратила́те."]},{"h":"Кондак 3","ps":["Си́лою Бо́жієй умерщвле́нна змі́я Фео́дором Стратила́том ви́дівше, Євхаї́тський град і всі лю́діє окре́стния чудя́шеся зіло́ і взива́ху глаго́люще: «Ве́лій єсть Бог Фео́доров, сей єсть Бог і́стинний»,– Єму́же ми вопіє́м: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я оби́чай благи́й но́щію моли́тися неуси́пно, Фео́доре святи́й, виді́нія боже́ственнаго сподо́бился єси́: покро́ву хра́мини, я́ко отве́рсту яви́вшуся і сві́ту небе́сному, я́ко огню́ ве́лію, осія́вшу тя; та́кже і глас сли́шал єси́ сви́ше глаго́лющ: «Дерза́й, Фео́доре с тобо́ю бо єсьм». Сим позна́л єси́, я́ко вре́м'я приї́де страда́нія твоєго́ за Христа́, возвесели́ся ду́хом. Ті́мже вопіє́м ті:","Ра́дуйся, я́ко сла́ву неізглаго́ланную Христа́ Бо́га узрі́л єси́.","Ра́дуйся, я́ко і преми́рних виді́ній зри́тель бил єси́.","Ра́дуйся, я́ко і на землі́ небе́сния собесі́дники імі́л єси́.","Ра́дуйся, вели́ких бо Та́їн открове́ній в земно́й жи́зні сподо́бился єси́.","Ра́дуйся, проро́чеськоє просвіще́ніє.","Ра́дуйся, світи́льниче ми́сленний, сві́том Христо́вим облиста́ємий.","Ра́дуйся, святи́й великому́чениче Фео́доре, Вели́кий Стратила́те."]},{"h":"Кондак 4","ps":["Бу́рю муче́ній бли́зящуся разумі́в, си́це моли́лся єси́ со слеза́ми, блаже́нне Фео́доре, Христу́ Бо́гу: «Го́споди, Бо́же, всеси́льний, бу́ди мі ми́лостив і соблюди́ м'я от пре́лести вра́жия, да не пора́дуються вразі́ мої́». Та́коже і ми с тобо́ю Бо́гу вопіє́м: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав злочести́ваго царя́ прельсти́тельния глаго́ли, я́ко да же́ртви і кади́ли і арома́ти принесо́ша ме́рзьким бога́м, Фео́доре треблаже́нне, сокруши́л єси́ я в нощ єди́ну і, раздроби́во вся і́доли зла́ти і сре́бряни в ча́сти ма́ли, разділи́л єси́ я си́рим і убо́гим. Сего́ ра́ди неустраши́мому твоєму́ по́двигу вельми́ див'я́щеся, си́це вопіє́м:","Ра́дуйся, прему́дростію слове́с твої́х безсту́днейшаго царя́ посрами́вий.","Ра́дуйся, сла́ву Бо́га жи́ва і і́стинна пред язи́ки пропові́давий.","Ра́дуйся, я́ко воі́стину Фео́дор, є́же сказу́ється дар Бо́жий, яви́лся єси́.","Ра́дуйся, я́ко ни́ні со а́нгели і ли́ки му́чеников блаже́нне ра́дуєшися.","Ра́дуйся, я́ко дерзнове́ніє імі́яй к Бо́гу, от скорбе́й і страсте́й нас всіх ізбавля́єши.","Ра́дуйся, святи́й великому́чениче Фео́доре, Вели́кий Стратила́те."]},{"h":"Кондак 5","ps":["Богоме́рзькия і́доли єгда́ я́ко зла́то і сребро́ оби́чно рассе́к у́си руко́ю челові́чеською, безу́мнаго царя́ нечести́ваго поруга́л єси́, великому́чениче, глаго́ля єму́: «Ти кла́няєшися бога́м ме́ртвим, аз же поклоня́юся Бо́гу Живо́му». Єму́же с тобо́ю і ми поклоня́ємся, взива́юще: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів нечести́вий мучи́тель ті́ло твоє́ честно́є на муче́ніє предає́мо, руга́шеся тебі́, страстоте́рпче. Ти же, святи́й, вся сія́ му́жественно терп'я́, нічто́же і́но глаго́лал єси́ то́чію: «Сла́ва Тебі́, Бо́же мой!» Терпі́нію твоєму́ див'я́щеся, си́це вопіє́м ті:","Ра́дуйся, жи́лами воло́вими і пру́тьми олов'я́нними безпоща́дно біє́мий.","Ра́дуйся, мно́гіє ра́ни к ра́нам і́мже ність числа́, от мучи́теля претерпі́вий.","Ра́дуйся, я́ко вінці́ побі́дния та́ко от Христа́ прия́вий.","Ра́дуйся, твої́ми ко Христу́ хода́тайстви ві́рния спаса́яй.","Ра́дуйся, святи́й великому́чениче Фео́доре, Вели́кий Стратила́те."]},{"h":"Кондак 6","ps":["Пропові́дник сла́ви Христо́вой яви́лся, в темни́цю вве́ржен бил єси́, страстоте́рпче Фео́доре, неі́стовим мучи́телем ру́ці і но́зі імі́яй свя́зана і нічесо́же яди́й да́же до дній п'яти́. А́нгел же свят прише́д разріши́ти ти свя́зана, да вопіє́ши Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ша по́чести твоя́ Фео́доре. Я́коже бо іногда́ Христо́с Госпо́дь наш от Пила́та, та́кожде і ти, блаже́нне, от Лики́нія царя́ на кресті́ про́п'ят бил єси́, ру́ці і но́зі імі́я пригвожде́нна. Сего́ ра́ди при́йдем всі ві́рни пі́сненними вінці́ Фео́дора Му́ченика пресла́внаго велича́єм глаго́люще:","Ра́дуйся, ко кресту́ пригвожде́нний.","Ра́дуйся, стрі́ли о́стрими і гво́здієм прободе́нний.","Ра́дуйся, мече́м усі́ченний. Ра́дуйся, вся́кими хитростьми́ болі́зней предупрежде́нний.","Ра́дуйся, я́ко в муче́ніїх непрекло́нен і непобіди́м яви́лся єси́.","Ра́дуйся, святи́й великому́чениче Фео́доре, Вели́кий Стратила́те."]},{"h":"Кондак 7","ps":["Хотя́ от земни́х разріши́тися і на дре́во вшед уя́звленною пло́тію, великому́чениче Фео́доре, си́це моли́лся єси́ ко Го́споду: «Пом'яни́ м'я, Го́споди, претерпева́юща крест Тебе́ ра́ди». Єму́же і ми с тобо́ю вопіє́м: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ва по страда́нії яви́ А́нгел Госпо́день, Фео́дора му́ченика, в пе́рвую бо стра́жу но́щі ви́сящу тому́ на кресті́ сни́де с небесе́ і снять со креста́ і сотвори́ всего́ ці́ла і здра́ва, я́коже і пре́жде, і лобза́я рече́ єму́: «Ра́дуйся і укріпля́йся, Фео́доре, се бо с тобо́ю Госпо́дь». Сего́ ра́ди і ми со безпло́тними ку́пно воззове́м тому́ глаго́люще:","Ра́дуйся, цілова́ніє а́нгельськоє приє́мий.","Ра́дуйся, спаси́тельную страсть Зижди́теля ізобрази́вий.","Ра́дуйся, во вся́ких ну́ждах предста́тельством твої́м спаса́яй.","Ра́дуйся, вся́ку душегуби́тельную печа́ль і обстоя́ніє отгоня́яй.","Ра́дуйся, чуде́с мно́жество су́щим в ми́рі подава́яй.","Ра́дуйся, ві́рним сердца́ неви́димо подава́яй.","Ра́дуйся, святи́й великому́чениче Фео́доре, Вели́кий Стратила́те."]},{"h":"Кондак 8","ps":["Стра́нноє о тебі́ содіва́ється, блаже́нне Фео́доре, мучи́тель бо злочести́вий мня тя ра́сп'ята ме́ртва су́ща, оста́ви ті́ло твоє́ на кресті́ ви́сяща, ти же от А́нгела ціл і здрав бив, на́чал єси́ пі́ти Го́сподеві піснь хвале́бную: Аллилу́я."]},{"h":"Ікос 8","ps":["Всего́ тя істреби́ти хотя́ще мучи́тель, сего́ ра́ди і со́тник повелі́ поя́ти ті́ло твоє́ со креста́ і в ковче́г олов'я́н вложи́ти і в пучи́ну морську́ю вве́ргнути, да ніка́ко христия́не є во́зьмуть і че́стно погребу́ть. Со́тници же зна́менія мно́гая і ве́лія от свята́го узрі́вше, ко Христу́ обрати́вшася; сего́ ра́ди і ми чту́ще честну́ю му́ченика па́м'ять си́це вопіє́м:","Ра́дуйся, Небе́снаго Царя́ воєво́до предо́брий.","Ра́дуйся, ри́торе ізря́дний, па́че мудрецо́в ми́ра мудрі́йший.","Ра́дуйся, вся ми́ра сего́ кра́сная ні во что же вміни́вий.","Ра́дуйся, терпі́нія соверше́ннійший о́браз всім показа́вий.","Ра́дуйся, в Сіо́ні го́рнем со А́нгели і святи́ми ку́пно всели́вийся.","Ра́дуйся, хода́тай те́плий за ни пред Бо́гом яви́вийся.","Ра́дуйся, святи́й великому́чениче Фео́доре, Вели́кий Стратила́те."]},{"h":"Кондак 9","ps":["Вся́кая похвала́ подоба́єть тебі́ великому́чениче Фео́доре, претерпі́в бо крест і по страда́нії па́ки ціл і здрав со креста́ соше́д, А́нгелом чуде́сним ді́йствієм, неве́рниє со́тники ца́рськия і во́їни мно́гі пре́жде нечести́виє просвіти́л єси́ і научи́л єси́ ві́ровати Христу́ Бо́гу і Пі́ти Єму́ ку́пно с тобо́ю: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я, сказу́яй сла́ву Бо́жию неізче́тними зна́менії твої́ми, яви́лся єси́ ми́ру сла́во му́чеников Фео́доре, от тебе́ бо ісціле́ніє неоску́дно почерпа́єм, всі к тебі́ с ві́рою прибіга́ющії і стра́сті твої́ воспіва́ющії си́це:","Ра́дуйся, у́зники мно́гі от уз разріши́вий.","Ра́дуйся, две́рі темни́чния сло́вом єди́ним отверза́яй.","Ра́дуйся, неду́жним ісціле́ніє подава́яй.","Ра́дуйся, де́моном злим одержи́мия свобожда́яй.","Ра́дуйся, то́чію прикаса́ющієся ко оде́жді твоє́й а́біє ісціля́яй.","Ра́дуйся, вмі́сто кро́вних ка́пель ісціле́ній то́ки одождя́яй.","Ра́дуйся, святи́й великому́чениче Фео́доре, Вели́кий Стратила́те."]},{"h":"Кондак 10","ps":["Спаси́тельную ві́ру восприя́вша всі лю́діє ве́лія зна́меніє твоя́ зря́щії, треблаже́нне Фео́доре, ті́мже і́долов ме́рзьких отве́ргше, Христу́ приліпи́шася, глаго́люще: «Ве́лій бо єсть Бог Фео́доров, сей єсть Бог і́стинний»,– Єму́же при́сно вопіє́м: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну необори́мую му́жества твоєго́ во́їне Христо́в, не одолі́в лю́тий мучи́тель, уби́йством на тя ди́шуще і кро́ве твоєя́ а́ки пес а́лчний жа́ждал, посла́ мече́м уби́ти тя, ти же помоли́вся і зна́менієм кре́стним зна́менався, во́лею приклони́л єси́ под меч главу́ твою́. Твоє́ усікнове́ніє чту́ще си́це вопіє́м ті:","Ра́дуйся, мече́м смерть му́ченичеськую восприя́вий.","Ра́дуйся, во успе́нії своє́м зна́менія мно́гі сотвори́вий.","Ра́дуйся, ві́ру і любо́в Христо́ву да́же до сме́рти сохрани́вий.","Ра́дуйся, я́ко во ви́шніх черто́зіх со а́нгели і святи́ми всели́лся єси́.","Ра́дуйся, я́ко за грі́шния те́плий ко Христу́ предста́тель яви́лся єси́.","Ра́дуйся, о душа́х на́ших непреста́нний моли́твенниче.","Ра́дуйся, святи́й великому́чениче Фео́доре, Вели́кий Стратила́те."]},{"h":"Кондак 11","ps":["Пі́ніє надгро́бноє со свіща́ми і кади́ли воспі́ша лю́діє всі, честь тебі́ воздаю́ще, Фео́доре, єгда́ глава́ твоя́ честна́я мече́м усі́чена бисть, ті́мже взя́ше ті́ло твоє́ свято́є і в мі́сті наро́чіте положи́вша є, посліди́ же і в Євхаї́тський град принесо́ша, Христа́ Бо́га сла́в'яще і пою́ще Єму́ піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́том зна́менія ізря́днаго порази́л єси́ нечести́вия сараци́ни на честни́й храм твой, і́же в Ка́рсаті, наше́дших, єгда́ стріло́ю устріли́ о́браз твой, а́біє істече́ кров в обличе́ніє тіх омраче́нних безу́мієм. Ті́мже зна́менію сему́ чудя́щеся, ві́рно вопіє́м ті, чудотво́рче Фео́доре:","Ра́дуйся, я́ко безу́міє сараци́н посрами́л єси́.","Ра́дуйся, я́ко Це́рков Бо́жию от поруга́нія огради́л єси́.","Ра́дуйся, я́ко о́браз твой сві́тлий чудотво́рен яви́лся єси́.","Ра́дуйся, я́ко і́м'я твоє́ і в неві́рних просла́вил єси́.","Ра́дуйся, па́че ві́рния к тебі́ прибіга́ти в мольба́х научи́л єси́.","Ра́дуйся, святи́й великому́чениче Фео́доре, Вели́кий Стратила́те."]},{"h":"Кондак 12","ps":["Благода́тним зна́менієм не вразуми́вшеся неві́рнії сараци́ни храм твой святи́й оскверни́ша і о́бразу твоєму́ честно́му поруга́тися мня́ху, оба́че смерть лю́ту по ма́ліх днех прия́ху, ві́рни же всі іко́ну твою́ святу́ю, я́ко чудоде́йственну вельми́ чту́ще взива́ють Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ть ди́вния по́двиги і чудеса́ твоя́ всі ві́рни по всей землі́ христия́нстій по вся дні в неісчи́слимих хра́мах і оби́теліх во і́м'я твоє́ созда́нних, собира́ющеся і пі́сненними вінці́ тя велича́юще, великому́чениче Фео́доре Стратила́те, ті́мже і нас, па́м'ять твою́ днесь сві́тло пра́зднующих, пом'яни́ і защити́, да любо́вію зове́м ті вопію́ще:","Ра́дуйся, я́ко мольби́ грі́шних приє́млеши.","Ра́дуйся, я́ко ско́рби душе́вния утоля́єши.","Ра́дуйся, я́ко страсте́й огнь укроща́єши.","Ра́дуйся, я́ко от вся́кия скве́рни пло́ті і ду́ха соблюда́єши.","Ра́дуйся, я́ко от іскуше́ній лука́ваго ізбавля́єши.","Ра́дуйся, я́ко моля́щихся у престо́ла Вседержи́теля помина́єши.","Ра́дуйся, Святи́й великому́чениче Фео́доре, Вели́кий Стратила́те."]},{"h":"Кондак 13","ps":["О, всехва́льний і всеблаже́нний Стратила́те, великому́чениче святи́й Фео́доре! Прийми́ сіє́ умиле́нноє моле́ніє на́ше, і ко Престо́лу Небе́снаго Царя́ Христа́ ско́ро вознеси́, да предста́тельством твої́м от вся́ких зол і напа́стей свободі́мся, вопію́ще Бо́гу при́сно: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і всея́ тва́рі Созда́тель яви́ тя Це́ркві Своє́й, я́ко страда́льця до́блественна і во́їна непобіди́ма, да всі по достоя́нію страда́нія твоя́ восхва́лять, страстоте́рпче Фео́доре. Сего́ ра́ди і ми, я́ко му́ченика днесь чту́ще, восхваля́єм ті, вопію́ще:","Ра́дуйся, і́дольськаго служе́нія пре́лесть обличи́вий.","Ра́дуйся, я́рость безу́мнаго царя́ язи́чеськаго презрі́вий.","Ра́дуйся, сего́ ра́ди муче́нія ве́лія і ра́ни сме́ртния претерпі́вий.","Ра́дуйся, я́ко Христо́с от Пила́та, от Лики́нія царя́ пло́тію на кресті́ пригвожде́нний.","Ра́дуйся, от А́нгела Госпо́дня па́ки живо́т і крі́пость ди́вно восприя́вий.","Ра́дуйся, с ра́достію о Го́споді главу́ свою́ честну́ю под меч преклони́вий.","Ра́дуйся, святи́й великому́чениче Фео́доре, Вели́кий Стратила́те."]},{"h":"Кондак 1","ps":["Возбра́нному воєво́ді і сла́вному во страда́льціх во́їну, свято́му великому́ченику Фео́дору, прийді́те піснь хвале́бную вку́пі воспої́м. Ти же, великому́чениче, я́ко імі́я дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, святи́й великому́чениче Фео́доре, Вели́кий Стратила́те."]},{"h":"Молитва","ps":["О, пресла́вний і прехва́льний великому́чениче святи́й Фео́доре, вели́кий Стратила́те! Не отри́ни грі́шних сія́ ма́лия моли́тви і приноше́нія, но я́ко імі́я дерзнове́ніє ко Всеми́лостивому Влади́ке, потщи́ся к нам недосто́йним ско́рою твоє́ю по́мощію і яви́ся хода́тай за ни те́плий у Христа́ Бо́га, да не поги́бнем всі во греха́х на́ших, но да сотвори́ть с на́ми по вели́кой ми́лості Своє́й, да умири́ть мир і сохрани́ть нас от вся́каго зла́го обстоя́нія, да дасть нам ти́хоє і безм'яте́жноє житіє́ пожи́ти в чистоті́ і благоче́стії, і по ісхо́ді душ на́ших неосужде́нно предста́ти суди́лищу Єго́ і десна́го стоя́нія сподо́битися, да ви́ну поє́м і сла́вим Єго́ Всесвято́є і́м'я со Отце́м і Святи́м Ду́хом во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Воїнствосло́вієм і́стинним, страстоте́рпче, / Небе́снаго Царя́ воєво́да предо́брий бил єси́, Фео́доре, / ору́жіями бо ві́ри ополчи́лся єси́ му́дренно, / і побіди́л єси́ де́монов полки́, / і побідоно́сний яви́лся єси́ страда́лець. / ті́мже тя ві́рою // при́сно ублажа́єм."]},{"h":"Кондак, глас 2","ps":["Му́жеством ду́ші во ві́ру оболки́йся / і глаго́л Бо́жий, а́ки копіє́, в ру́ку взем, врага́ побіди́л єси́, / му́чеников преве́лій Фео́доре, // с ни́ми Христу́ Бо́гу моля́ся не преста́й о всіх нас."]},{"h":"Величання","ps":["Велича́єм тя, / страстоте́рпче святи́й Фео́доре, / і чтим честна́я страда́нія твоя́, / я́же за Христа́ / претерпі́л єси́."]}],"notes":[]},{"u":"Акафіст преподобному Нестору Літописцю, Печерському","e":"Akathist to our Venerable Father Nestor the Chronicler of the Caves","secs":[{"h":"Кондак 1","ps":["Ізбранников Бо́жиїх сожи́телю, і́ноче честни́й і летописче пресла́вний, о́тче преподо́бне Не́сторе, прийми́ приноси́мия с любо́вію смире́нния похвале́нія на́ша. Ти же, я́ко імі́я ве́ліє дерзнове́ніє на небесі́, моли́ся те́плі о страні́ на́шей і лю́діх єя́, во є́же ізба́витися нам от вся́каго зла, да зове́м ті:","Ра́дуйся, Не́сторе, землі́ Ру́ськия пе́рвий летописателю."]},{"h":"Ікос 1","ps":["А́нгельському і́ночеському житію́ поревнова́в і суєту́ ми́ра тлі́ннаго презрі́в, во ю́ности ра́нней прите́кл єси́, о́тче преподо́бне, во оби́тель Пече́рськую гра́да Ки́єва, к стопа́м основа́телей єя́ Анто́нія і Феодо́сія смире́нно припа́дая і о сопричтенії тя ко бра́тії усе́рдно моля́. Того́ ра́ди взива́єм ті:","Ра́дуйся, от ю́ности твоєя́ Бо́гу служи́ти вожделі́вий.","Ра́дуйся, благу́ю часть от у́тра житія́ твоєго́ ізбра́вий.","Ра́дуйся, мир і вся єго́ пре́лести оста́вивий.","Ра́дуйся, Го́спода всім се́рдцем возлюби́вий.","Ра́дуйся, Не́сторе, землі́ Ру́ськия пе́рвий летописателю."]},{"h":"Кондак 2","ps":["Ви́дя благо́є проізволе́ніє се́рдця твоєго́ і прови́дяще в тебі́ сосу́д благода́тний доброді́телей христия́нських, преподо́бний Феодо́сій с ра́достію ве́лією сопричисли тя ко бра́тії оби́телі своєя́ і чи́на і́ночеськаго тя удосто́ї, умиле́нно пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом богопросвіще́нним возлюби́л єси́, Богому́дре Не́сторе, науче́ніє кни́жноє і зіло́ к сему́ приліжа́, а́ки пчела́ трудолюби́вая, собира́я сладча́йший мед прему́дрості і умножа́я в душі́ твоє́й во спасе́ніє сокро́вище неіждива́ємоє позна́нія. Сего́ ра́ди досто́їн яви́лся єси́ похвали́ сицеви́я:","Ра́дуйся, Прему́дрость просвіще́нія книжнаго во мла́дости стяжа́вий.","Ра́дуйся, к собира́нію многоці́ннаго би́сера зіло́ прилежавий.","Ра́дуйся, ме́дом позна́нія і́стини от ю́ности усладивийся.","Ра́дуйся, сокро́вищем негиблемим му́дре обогати́вийся.","Ра́дуйся, Не́сторе, землі́ Ру́ськия пе́рвий летописателю."]},{"h":"Кондак 3","ps":["Си́лу духо́вную от Влади́ки своєго́ восприя́в, преподо́бне, Тому́ жизнь свою́ безраздельне посвяти́л єси́, воспіва́я благи́х Пода́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я дарова́ніє духо́вноє от Го́спода твоєго́, тала́нт тебі́ да́нний не скрил єси́, а́ки раб неради́вий, но Го́споду помога́ющу ті мно́гажди, доброді́телі в житії́ твоє́м умно́жил єси́, ра́бе благи́й і ві́рний, да просла́виться в тебі́ Творе́ць вся́чеських, ті́мже зове́м ті:","Ра́дуйся, вві́ренноє тебі́ сокро́вище му́дрости в землі́ не скривий.","Ра́дуйся, доброді́телей вертогра́д бога́тий духо́вно возрасти́вий.","Ра́дуйся, благи́й собира́телю бога́тства нетлі́ннаго.","Ра́дуйся, обріти́й блаже́нство Рая́ вожделі́ннаго.","Ра́дуйся, Не́сторе, землі́ Ру́ськия пе́рвий летописателю."]},{"h":"Кондак 4","ps":["Бу́рі страсте́й жите́йських уклони́лся єси́, уго́дниче Христо́в, во ути́шноє приста́нище святи́я оби́телі Пече́рськия дости́гши, іді́же с честни́ми насе́льники сея́ не престава́л єси́ пі́ти Спаси́телю твоєму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша наставле́ніє душеспаси́тельноє, от Богоно́снаго Феодо́сія і іни́х честни́х оте́ць, тебі́ неоску́дно подава́ємоє, сему́ со тща́нієм послі́довал єси́ в пещерном затворе́нії твоє́м, моли́твою, поще́нієм і о пло́ті нераді́нієм укріпля́єм в по́двизі многотрудном житія́ і́ночеськаго. Сего́ ра́ди сли́шиши ни́ні хвале́нія сицева́я:","Ра́дуйся, от ю́ности во мрак пещерний, спасе́нія ра́ди, всели́вийся.","Ра́дуйся, та́мо непреста́нною моли́твою от треволне́нія жите́йськаго оградивийся.","Ра́дуйся, я́ко в по́двизі твоє́м наста́вника богому́драго Феодо́сія імі́л єси́.","Ра́дуйся, наставле́нієм сего́ послушливо внима́л єси́.","Ра́дуйся, Не́сторе, землі́ Ру́ськия пе́рвий летописателю."]},{"h":"Кондак 5","ps":["Боготе́чною стезе́ю текл єси́, о́тче пресла́вний, нічесо́же су́єтнаго жела́я, но гра́да го́рняго, ві́чнаго взиску́я, Го́споду же неуста́нно поя́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя неуста́нния труди́ твоя́, ко спасе́нію душі́ направля́ємия і ра́дующеся бра́тськи о преуспі́янії твоє́м в по́двизі житія́ мона́шеськаго, всі і́ноці оби́телі Пече́рськия восхваля́ху тя си́це:","Ра́дуйся, тру́дниче неуста́нний, я́ко мзди благи́я досто́їн яви́лся єси́.","Ра́дуйся, подви́жниче до́брий благоче́стія, я́ко в по́двизіх твої́х не ізнемога́л єси́.","Ра́дуйся, о́браз честни́й житія́ і́ночеськаго бра́тії явля́яй.","Ра́дуйся, в смире́нії і кро́тости душе́вній всіх при́сно наставля́яй.","Ра́дуйся, Не́сторе, землі́ Ру́ськия пе́рвий летописателю."]},{"h":"Кондак 6","ps":["Провозві́стника сла́ви оте́чеськия обрі́те тя, Не́сторе досточу́дне, страна́ Ру́ськая, уві́дів бо минувшия судьби́ єя́, письмени́ пре́дал єси́ вся в науче́ніє, наставле́ніє і назида́ніє родо́м гряду́щим, да ті́ї уві́дівше промишле́ніє Бо́жиє к язи́ку Словенську, воспою́ть Благо́му Промисли́телю своєму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, я́ко со́лнце світоно́сноє, в Ру́сстій землі́, Богоблаже́нне о́тче, неві́дінія бо мрак глубоча́йший, от ві́ка ю покрива́ющий, твої́ми писа́ньми пе́рвіє озари́л єси́, к сві́ту ві́дінія і Богопозна́нія соо́тчичі твоя́ призива́я, от ни́хже сицево́є похвале́ніє досто́йно восприя́л єси́:","Ра́дуйся, мглу неві́дінія ва́рварськаго в наро́ді на́шем разгна́вий му́дрости сія́нієм.","Ра́дуйся, просвіще́нію оте́чества послужи́вий твої́м летописанієм.","Ра́дуйся, над сим усе́рдно до кончи́ни живота́ твоєго́ тружда́яйся.","Ра́дуйся, ко труду́ писа́нія те́плою моли́твою уготовляяйся.","Ра́дуйся, Не́сторе, землі́ Ру́ськия пе́рвий летописателю."]},{"h":"Кондак 7","ps":["Хотя́й свиді́телем ди́внаго чудеси́ тебі́, о́тче, яви́ти Госпо́дь Вседержи́тель, внуши́ та́йно ігу́мену Пече́рському Іоа́нну, да вві́рено ті бу́деть, ку́пно со іни́м от бра́тії, іскопа́ти погребе́нноє в землі́ ті́ло наста́вника твоєго́ преподо́бнаго Феодо́сія, по симинадесятіх лі́тіх от кончи́ни сего́, во увіре́ніє благода́ті Бо́жия, на нем явле́нній. Ті́мже узрі́вши того́ во гро́бі нетлі́нна су́ща і чудеса́ ве́лія істоча́юща, ра́дуяся воспі́л єси́ со і́ноки Печерськими чуде́с Соді́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий труд на по́льзу і в науче́ніє христия́ном под'ял єси́, преподо́бне Не́сторе, во є́же списа́ти житіє́ вели́каго уго́дника преподо́бнаго Феодо́сія, і́же бі ку́пно со богоно́сним Анто́нієм, первоначальником богоуго́днаго і́ночеськаго житія́ в землі́ Ру́сстій і строї́тель оби́телі Пече́рськия, є́йже уста́в от сла́вния кино́вії Студі́йськия восприя́в, той во ві́ки соблюда́ти в ней запові́да. Ті́мже і ми, благода́рні су́ще за таково́є твоє́ к нам недосто́йним попече́ніє, єдиноду́шно сла́вим тя, о́тче, та́ко:","Ра́дуйся, житія́ преподо́бнаго Феодо́сія благогові́йний сказа́телю.","Ра́дуйся, сему́ в по́двизі твоє́м ре́вностний подража́телю.","Ра́дуйся, по́вістію твоє́ю ві́рния уті́шивий.","Ра́дуйся, то́ю ко і́ночеському по́двигу мно́гія подви́гнувий.","Ра́дуйся, Не́сторе, землі́ Ру́ськия пе́рвий летописателю."]},{"h":"Кондак 8","ps":["Стра́нник і пришле́ць бил єси́, Не́сторе, на землі́, ко вре́менному і тлі́нному битію́ ніка́коже приліпля́яйся, но ум і се́рдце устремля́я ко блаже́нству нескончаємому Оте́чества Небе́снаго, іді́же ни́ні со А́нгели во весе́лії зове́ши: Аллилу́я."]},{"h":"Ікос 8","ps":["Все житіє́ твоє́, Боголюбе́зне о́тче, Спаси́телю твоєму́ і бли́жнім посвящено бисть. Се́рдцем бо чи́стим за́повідь Христо́ву восприї́м, любве́ зако́н благода́тний іспо́лнил єси́, в мі́ру сил тружда́яся на по́льзу бра́тій твої́х і ви́ну прославля́я Возлю́бленнаго тобо́ю Го́спода. Ті́мже от Того́ прославле́ніє на небесі́ улучи́в, сли́шиши на землі́ блажа́щих тя похвали́ си́ми:","Ра́дуйся, сві́тлий о́бразе братолю́бія і смире́нія.","Ра́дуйся, благи́й наста́вниче трудолю́бія і терпі́нія.","Ра́дуйся, спасе́нію бли́жніх крі́пці поревнова́вий.","Ра́дуйся, похвали́ от сих досто́йно прия́вий.","Ра́дуйся, Не́сторе, землі́ Ру́ськия пе́рвий летописателю."]},{"h":"Кондак 9","ps":["Вся́коє наслажде́ніє плотсько́є возненави́діл єси́, преподо́бне о́тче Не́сторе, і житіє́ і́ночеськоє возлюби́л єси́, ті́мже і Госпо́дь возлюби́ тя, просла́ви і дарова́ нам, я́ко моли́твенника усе́рднаго, ви́ну пою́щаго Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́й многословних па́че кра́ткими словеси́ твої́ми зе́млю Оте́чества на́шего просла́вил єси́, му́дре наста́вниче, от «По́вісти вре́менних літ»: уві́діхом бо отку́ду єсть пошла Ру́ськая земля́, ю́же ве́лією сино́внею любо́вію возлюби́л єси́. Сего́ ра́ди си́нове словенорусстії во вся ро́ди і до ни́ні восхваля́ють тя, глаго́люще:","Ра́дуйся, ри́тори сла́вния в простоті́ сло́ва твоєго́ превосходя́й.","Ра́дуйся, му́дростію науче́нія твоєго́ нас любо́вію озаря́яй.","Ра́дуйся, Оте́чества земна́го ві́рний люби́телю.","Ра́дуйся, о бла́гі землі́ твоєя́ усе́рдний ревни́телю.","Ра́дуйся, Не́сторе, землі́ Ру́ськия пе́рвий летописателю."]},{"h":"Кондак 10","ps":["Спасе́нія путь у́зький і многотрудний во́лею ізбра́л єси́, Богоно́сне, і лиця́ твоєго́ ніколи́же всп'ять обрати́л єси́, к світоза́рному Со́лнцю пра́вди Христу́ Бо́гу ви́ну о́чі твоя́ обраща́яй і Того́ прославля́я пі́снію хвалебною: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю упова́нія несумні́ннаго огради́л єси́, преподо́бне, ду́шу твою́ от вся́каго іскуше́нія і собла́зна, ві́рою крі́пкою познава́я полноту́ благода́ті і милосе́рдія Созда́теля твоєго́. Того́ ра́ди сли́шиши от нас, недосто́йних і отча́янієм коле́блемих, такова́я:","Ра́дуйся, в душі́ возрасти́вий благоуха́нний цвіт доброді́телі.","Ра́дуйся, ві́рою неви́димих, а́ки ви́димих, ча́ємих і ожида́ємих, я́ко су́щих, і́стинний свиді́телю.","Ра́дуйся, благоче́стія христия́нськаго нелі́ностний побо́рниче.","Ра́дуйся, ізнемога́ющих в тягостном сомні́нії благи́й укріпи́телю і помо́щниче.","Ра́дуйся, Не́сторе, землі́ Ру́ськия пе́рвий летописателю."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє от сино́в Ру́ських по достоя́нію приє́млющи, о́тче досточу́дне, любо́вію твоє́ю не преста́й заступа́ти от всіх бід і скорбе́й зе́млю оте́чеськую на́шу, в не́йже ви́ну, прославля́ється і́м'я Госпо́днє пі́снію: Аллилу́я."]},{"h":"Ікос 11","ps":["Світолу́чними сія́нії любві́ Боже́ственния уязви́вийся, летописче пресла́вне, о́брази сея́ яви́л єси́ житіє́м страстоте́рпець святи́х благові́рних бра́тій Бори́са великоду́шнаго і Глі́ба кро́ткаго, да їм послі́дующе, доброді́телі братолю́бія, отечестволюбія, смире́нія і послуша́нія приобря́щем, тебі́ же, дія́ній сих списа́теля богому́дра, восхва́лим си́це:","Ра́дуйся, я́ко благода́ть Боже́ственная на тебі́ неоску́дно почива́ше.","Ра́дуйся, я́ко то́ю умудряєм, уго́дники Бо́жия с любо́вію просла́вил єси́.","Ра́дуйся, о бла́гі землі́ твоєя́ неуста́нний моли́твенниче.","Ра́дуйся, отечестволюбцем і му́дрости позна́нія іскателем при́сний помо́щниче.","Ра́дуйся, Не́сторе, землі́ Ру́ськия пе́рвий летописателю."]},{"h":"Кондак 12","ps":["Благода́тний істо́чник наставле́ній Богоуго́дних обріто́хом в тебі́, о́тче Не́сторе, житіє́м бо і списа́ньми твої́ми вся утвержда́єши ше́ствовати неукло́нно во слід Єди́ному Человіколю́бцю і Спаси́телю на́шему Бо́гу, зову́ще Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Богоуго́дноє житіє́ твоє́, Не́сторе пресла́вне, со умиле́нієм прославля́єм труди́ і по́двиги твоя́, ї́миже Христу́ Спа́су зіло́ угоди́л єси́, і восхваля́єм ди́вноє смотре́ніє Бо́жиє на тебі́, в нетлі́нії моще́й твої́х дони́ні явля́ємоє. Почита́я же ми́рную і непости́дную кончи́ну твою́, поклоня́ємся неізследимому Про́мислу Всеви́шняго, сподо́бльшаго тя прича́стника би́ти неізрече́нния сла́ви Своєя́ в селе́ніїх пра́ведних, отоню́дуже приклони́ у́хо твоє́ ко гла́сом на́шим, взивающим ті си́це:","Ра́дуйся, ко́зні, кова́рства і зло́би де́монськия расто́ргнувий.","Ра́дуйся, ду́хом твої́м невозбра́нно в го́рняя оби́телі востекший.","Ра́дуйся, во мра́ці пеще́рнім ті́лом твої́м нетлі́нно до днесь почива́яй.","Ра́дуйся, от моще́й твої́х мно́гую по́мощ чту́щим тя неоску́дно подава́яй.","Ра́дуйся, Не́сторе, землі́ Ру́ськия пе́рвий летописателю."]},{"h":"Кондак 13","ps":["О, пресла́вний уго́дниче Бо́жий, Богому́дре о́тче Не́сторе! При́зри любо́вію твоє́ю с висоти́ небе́сния на скорб і сле́зи собра́тій твої́х земни́х і умоли́ Всемилосерднаго Го́спода ізба́вити зе́млю Ру́ськую і чад єя́ от бід і напа́стей, да восхва́лим человіколю́біє і щедро́ти Єго́, воспіва́юще ви́ну: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельському і́ночеському житію́ поревнова́в і суєту́ ми́ра тлі́ннаго презрі́в, во ю́ности ра́нней прите́кл єси́, о́тче преподо́бне, во оби́тель Пече́рськую гра́да Ки́єва, к стопа́м основа́телей єя́ Анто́нія і Феодо́сія смире́нно припа́дая і о сопричтенії тя ко бра́тії усе́рдно моля́. Того́ ра́ди взива́єм ті:","Ра́дуйся, от ю́ности твоєя́ Бо́гу служи́ти вожделі́вий.","Ра́дуйся, благу́ю часть от у́тра житія́ твоєго́ ізбра́вий.","Ра́дуйся, мир і вся єго́ пре́лести оста́вивий.","Ра́дуйся, Го́спода всім се́рдцем возлюби́вий.","Ра́дуйся, Не́сторе, землі́ Ру́ськия пе́рвий летописателю."]},{"h":"Кондак 1","ps":["Ізбранников Бо́жиїх сожи́телю, і́ноче честни́й і летописче пресла́вний, о́тче преподо́бне Не́сторе, прийми́ приноси́мия с любо́вію смире́нния похвале́нія на́ша. Ти же, я́ко імі́я ве́ліє дерзнове́ніє на небесі́, моли́ся те́плі о страні́ на́шей і лю́діх єя́, во є́же ізба́витися нам от вся́каго зла, да зове́м ті:","Ра́дуйся, Не́сторе, землі́ Ру́ськия пе́рвий летописателю."]},{"h":"Молитва","ps":["О, преподо́бне о́тче, прему́дре наста́вниче і Боголюбе́зне подви́жниче Не́сторе Летописче! Предстоя́й со дерзнове́нієм престо́лу Ві́чния Сла́ви, не забу́ди нас грі́шних і недосто́йних, бу́рями страсте́й отягче́нних, і хода́тайством твої́м непреста́нним защити́ страну́ на́шу, тебі́ при́сную, і соотчії твоя́ от вся́ких зол і скорбе́й. Утверди́ се́рдця на́ша в правосла́вній ві́рі, оте́чество своє́ научи́ люби́ти і в братолю́бії крі́пці пребива́ти. Наста́ви нас на стезі́ спасе́нія, да моли́твами твої́ми, засту́пниче наш, вни́дем во ві́чноє Ца́рство сла́ви, восхваля́юще Го́спода і прославля́юще твоє́ заступле́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Вели́ких князе́й ру́ських дія́нія / і преподо́бних оте́ць Пече́рських житія́ і чудеса́ написа́вий, / своє́ же, Богому́дре Не́сторе, мно́гих ті ра́ди доброді́телей і́м'я / напи́сано на Небесі́ стяжа́вий, // моли́ і нам написа́тися в Кни́ги Живо́тния."]},{"h":"Кондак, глас 2","ps":["Я́ко сий Богоно́снаго Феодо́сія учени́к / і і́стинний житія́ того́ подража́тель, / пе́рвий честни́х єго́ моще́й самови́дець би́ти сподо́бился єси́, / я́же с про́чіїми святолі́пно прене́с, / наслі́дил єси́ с ті́миже Ца́рство Небе́сноє, // є́же получи́ти і нам, чту́щим тя, Го́сподеві моли́ся."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Не́сторе, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Пафнутію Боровському","e":"Akathist to our Venerable Father Paphnutius of Borovsk","secs":[{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче, вели́кий уго́дниче Христо́в, врачу́ благода́тний, бісо́в прогони́телю, всім любо́вію притекающим істоча́яй ми́лости ми́ро, восхваля́єм тя любо́вію, о́тче Пафну́тіє, ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, о́тче Пафну́тіє, Боровський чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць, прови́дя тя а́нгелом подража́теля во пло́ті іму́ща би́ти, от ю́на во́зраста облече́ тя во а́нгельський чин. Ти же отше́д от ми́ра і обле́кся во і́ночеськоє одія́ніє, крест на ра́мо взем, вседу́шно поте́кл єси́ во слід Распеншегося нас ра́ди Го́спода: скорб і труд возлюби́в, приліпи́лся єси́ Христу́ любо́вію і моли́твами. Ми же, благодаря́ще о сем Бо́га, похва́льная воспису́єм ті:","Ра́дуйся, послу́шателю Го́спода зову́ща: возьмі́те і́го моє́ на себі́;","ра́дуйся подви́жниче, по́двигом до́брим подвиза́вийся;","ра́дуйся, ізбра́вий путь ті́сний, веду́щий в живо́т;","ра́дуйся, смире́нієм висо́ких дости́гший.","Ра́дуйся, кротостью в зе́млю кро́тких всели́вийся;","ра́дуйся, ві́чноє ра́дованіє на небесі́ обрі́тший.","Ра́дуйся, засту́пниче наш, і нас помина́яй пред Бо́гом ра́дующихся о тебі́.","Ра́дуйся, о́тче Пафну́тіє, Боровський чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дяще бли́жнії і да́льнії ди́вноє о Бо́зі житіє́ твоє́, дарова́ніє ісціле́ній і сбитіє́ прорече́ній твої́х, вельми́ удивля́хуся і сла́в'яще Бо́га вопія́ху: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум твой в Боже́ственная впери́в і Бо́жиїм сві́том озари́вся, да́ри благода́тния явля́л єси́ в себі́, я́ко угль горя́щий огне́м Боже́ственним в тебі́, су́щая возгріва́я к любві́ Бо́жієй, та́кожде і су́щих с тобо́ю просвіща́я. Моли́ся у́бо о нас, покрови́телю наш, да ревну́я житію́ твоєму́ спасе́м душі́ на́ша і тебі́ благоприя́тно поє́м:","Ра́дуйся, разумі́нієм во́лі Бо́жієй і тайн Єго́ озаривийся;","ра́дуйся, сотвори́вий вся повелі́нная Христо́м;","ра́дуйся, в послушаніях монасти́рських, я́ко раб неключи́мий послужи́вий;","ра́дуйся, о́бразе Євангельського самоотверже́нія;","ра́дуйся, я́ко храм Бо́жий се́рдце твоє́ бисть;","ра́дуйся, я́ко оби́тель твою́ я́ко рай возделану імі́л єси́;","ра́дуйся, я́ко ве́лій во Ца́рствії Бо́жиєм, я́ко сотвори́вий і научи́вий наре́клся єси́.","Ра́дуйся, о́тче Пафну́тіє, Боровський чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою сви́ше облеки́й апо́столи Госпо́дь, облече́ тя, о́тче, в ри́зу спасе́нія, украси́ тя красото́ю доброді́телей і чуде́с да́ром, ми же благодаря́ще Бо́га Ди́внаго во святи́х Свої́х, вопіє́м: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще оби́тель тебі́, о́тче, почива́юща зді святи́ми моща́ми, ра́достію ісполня́ється і веселя́щися уми́льно тебі́ вопіє́ть:","Ра́дуйся, ізбра́нний сосу́де Свята́го Ду́ха;","ра́дуйся, по Бо́зі і Богоро́дице ра́досте на́ша і покро́ве;","ра́дуйся, ти́хоє приста́нище на́ше от молви́ гріхо́вния;","ра́дуйся, апо́стольських уче́ній ісполни́телю;","ра́дуйся, святи́х оте́ць подража́телю;","ра́дуйся, я́ко а́нгел, безстра́стієм просія́вий;","ра́дуйся, о́блаче, от зно́я страсте́й укриваяй.","Ра́дуйся, о́тче Пафну́тіє, Боровський чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́ря недоумі́нія смуща́єть м'я, ка́ко воспою́ тя, свя́те, зане́ бу́ря страсте́й і во́лни гріхо́в потопля́ють м'я; усли́ши у́бо вопль і сле́зи потопля́ємаго і бі́дствующему помози́, спаса́й м'я, прибі́жище моє́, да воспою́ благода́рно Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще боровскиє лю́діє, я́ко тобо́ю грі́шнії спаса́ються, неду́жнії ісціля́ються, бі́си прогоня́ються, гладнії пита́ються і скорб'я́щії уті́шени бива́ють, потеко́ша к тебі́ і бли́жнії і да́льнії, я́ко к ріці́, веселящей град Бо́жий і лю́ди. Па́че же во вре́м'я гла́да устремля́хуся всі к тебі́ с ві́рою в милосе́рдіє твоє́. Ти же і пита́л єси́ приходящия єжедневно я́ко ти́сящи і мно́жає, до́ндеже глад преста́. І та́ко просла́вися тобо́ю Оте́ць Небе́сний; ми же воспомина́юще о сем восхваля́єм тя усе́рдно си́це:","Ра́дуйся, милосе́рдий о́тче наш;","ра́дуйся, благода́тний врачу́ душ і тіле́с на́ших;","ра́дуйся, отча́янних в милосе́рдії Бо́жиєм утверди́телю;","ра́дуйся, смущенних умиротвореніє;","ра́дуйся, коле́блемих утвержде́ніє і па́дших возстановле́ніє;","ра́дуйся, ко́рмчий духо́вний ко спасе́нію;","ра́дуйся, гла́дних пита́телю, наги́х же одія́ніє і приста́нище ни́щих;","ра́дуйся, стра́ждущим утіше́ніє.","Ра́дуйся, о́тче Пафну́тіє, Боровський чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́ уві́дівше тя, преподо́бне Пафну́тіє, ученици́ твої́: Іо́сиф Волоколамський, Інноке́нтій, Ілия сро́дник твой і іні́ї, я́ко му́дрії волсви́, і́щуще Царя́ і Спа́са ми́ру і тобо́ю іспиту́юще путь, я́ко світи́льник держа́ще тя, достиго́ша того́ і ра́дуються ни́ні с тобо́ю, вопію́ще: Аллилу́я."]},{"h":"Ікос 5","ps":["От мно́гих люде́й враг творя́ше па́кості тебі́ і оби́телі твоє́й, ти же, учени́к сий Христо́в, люби́л єси́ враги́ твоя́, добро́ творя́ ненавидящим і моля́ся о них, ті́мже і побіжда́л єси́ благи́ми зла́я. Сего́ ра́ди Це́рков Свята́я восхваля́єть тя:","Ра́дуйся, боровськая свіще́, присногоря́щая пред Бо́гом;","ра́дуйся, благода́тная луче́ сія́ющая от со́лнця Христа́ Бо́га;","ра́дуйся, непоколеби́мий терпі́нія сто́лпе;","ра́дуйся, о́бразе кро́тости і незло́бія;","ра́дуйся, моли́твенниче за враги́ твоя́;","ра́дуйся, я́ко уста́ єси́ Бо́жия, ізводящая от недосто́йнаго досто́йноє;","ра́дуйся, миротво́рче, тому́жде боголі́пно і нас науча́яй.","Ра́дуйся, о́тче Пафну́тіє, Боровський чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник ві́ри і упова́нія на Бо́га ди́вний яви́лся єси́, преподо́бне Пафну́тіє єгда́ бо скорб'я́ху бра́тія, я́ко не імі́яху риб ко дню Сві́тлаго Воскресе́нія Христо́ва, глаго́лал єси́ о упова́нії на Бо́га; в на́вечерії же Сві́тлаго дне яви́шася на ма́лом пото́ці ри́би мно́зі. Та́ко упова́ніє на Го́спода не посрами́ тя, і просла́вивше Бо́га, всі вопія́ху: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, преподо́бне, світ а́нгельськия чистоти́: во пло́ті я́ко безпло́тен, преподо́бне, ревни́телю цемудрія. Сего́ ра́ди восхваля́єм тя:","Ра́дуйся, похвалі́ Творця́ вся́чеських і Присноді́ви;","ра́дуйся, подража́вши Іо́сифу цілому́дрієм;","ра́дуйся, Мойсе́ю Угрину собрате;","ра́дуйся, Крести́телю Госпо́дню поревнова́вий;","ра́дуйся, собла́зни і іскуше́нія дале́че отри́нувий;","ра́дуйся, ю́ним покро́ве і ста́рцем сві́тлосте;","ра́дуйся, недремлющий блюсти́телю мона́хов і по́стников украше́ніє;","ра́дуйся, я́ко світи́ло небе́сноє земни́м би́вий;","ра́дуйся, сожи́телю а́нгелом;","ра́дуйся, боровськая похвало́ і засту́пниче наш пред Бо́гом.","Ра́дуйся, о́тче Пафну́тіє, Боровський чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́й отгна́ти от святи́я Це́ркве вся́коє богоме́рзькоє злосмра́діє, яви́лся єси́ я́ко благово́нноє ми́ро житіє́м твої́м і сло́вом і́стини, апо́стольських же і собо́рних уче́ній, о́тче, іспо́лненний сосу́д бил єси́, ізгоня́ із оби́телі глаго́лющих проти́вная. Тім же свята́я Це́рков ублажа́єть тя і ми спасе́ннії вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя Но́я спасенного ковче́га оби́телі твоє́й показа́ Бог хотя́щим спасти́ся: наказу́я пото́пом гні́ва своєго́ преслушающих тя і па́ки ми́луя ка́ющихся, ми же благогові́йно мо́лим тя: покри́й не́мощі на́ша, о́тче, милосе́рдієм твої́м і смире́нною любо́вію, і сподо́би пі́ти:","Ра́дуйся ре́вностний учениче́ Христо́в;","ра́дуйся, притрепетний служи́телю Стра́шних Та́їн;","ра́дуйся, блюсти́телю Правосла́вія;","ра́дуйся, храни́телю чу́дний обі́тов мона́шеських;","ра́дуйся, ми́лостивий засту́пниче кающимся;","ра́дуйся, помога́яй і нам соблюда́ти обі́ти на́ші Бо́гу.","Ра́дуйся, о́тче Пафну́тіє, Боровський чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нен і ди́вен бил єси́ на землі́, істий же подража́тель небе́сним житіє́м, сло́вом і молча́нієм, я́ко умили́тися видящим тя. Прийдо́ша бо от кня́зя слузи́ буйнії, во зло́бі хотя́ще сожещи́ оби́тель твою́, єгда́ же узрі́ша тя, а́ки а́нгела ти́ха і сві́тла, внеза́пу применишася на кро́тость і мно́зі та́ко уклони́шася от зла і сотвори́ша бла́го от сли́шанія і виді́нія твоєго́, ми же прославля́юще о сем Бо́га, уми́льно вопіє́м ті: Аллилу́я."]},{"h":"Ікос 8","ps":["Возведи́ о́крест о́чі твої́, о́тче, і виждь: се бо мно́гая ча́да твоя́, с ра́зних стран прийдо́ша к тебі́ да́ри нося́ще, па́че же с ві́рою і любо́вію к засту́пнику і уті́шителю своєму́ в ско́рбіх і ну́ждах і припа́дающе мо́лять тя: простри́ ру́ку по́мощі тре́бующим, усли́ши нас із глубини́ душі́ взива́ющих:","Ра́дуйся, хода́таю наш у Бо́га вре́менних і ві́чних благ;","ра́дуйся, сія́ніє нам Бо́жієй ми́лости;","ра́дуйся, дерзнове́ніє на́ше к Бо́гу;","ра́дуйся, я́ко ми́лостива єго́ обріта́єм к нам;","ра́дуйся, я́ко тобо́ю от гні́ва Бо́жия ізбавля́ємся.","Ра́дуйся, о́тче Пафну́тіє, Боровський чудотво́рче."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ челові́чеськоє удиви́ся а́нгельському житію́ твоєму́ на землі́: попра́л бо єси́ бісо́в, я́ко прах под нога́ма, низложи́в їх шата́нія, разогнав собла́знов тьму і вся стрі́ли лука́ваго на главу́ єго́ обрати́в: сорасп'я́лся єси́ Христу́ і научи́л єси́ мно́гих со стра́хом пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії не возмо́гуть по до́лгу восхвали́ти тя, преподо́бне, то́чію а́нгели досто́йно восхваля́ють а́нгельськими пі́нії, от нас же, я́ко із уст младе́нець прийми́ хвалу́ сію́:","Ра́дуйся, похвало́ а́нгелов, мона́хов же і всея́ Святи́я Це́ркве;","ра́дуйся, вше́дий в ра́дость Го́спода Бо́га Твоєго́;","ра́дуйся, Патріа́рхом в угожде́нії Бо́гу поревнова́вий;","ра́дуйся, проро́ков да́ра сподобленний;","ра́дуйся, апо́стольськая уста́;","ра́дуйся, му́чеником соучастниче в расп'я́тії пло́ті і в я́звах Госпо́дніх на ті́лі твоє́м носимих;","ра́дуйся, ми́ру уме́рий, Христу́ же Єди́ному пожи́вий;","ра́дуйся, не забива́яй і нас заблу́ждших, призива́ющих тя;","ра́дуйся, о́тче, низпосилаяй нам с небесе́ ми́лость твою́;","ра́дуйся, дале́че провозгласивий: разумі́йте язи́ци, я́ко с на́ми Бог.","Ра́дуйся, о́тче Пафну́тіє, Боровський чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́щії притека́ху к тебі́, до́брому па́стирю, указа́телю путе́й Госпо́дніх, си́льному о Го́споді. Ти же я́ко імі́яй дарова́ніє прозрі́нія, всіх любе́зно прийма́л єси́, то́чію, іни́я па́ки отсила́я, оба́че ніколи́же глаго́ля о них зла́я, а́ще і ві́дий, ми же благодаря́ще Бо́га, ди́внаго во святи́х свої́х, вопіє́м: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну тя неруши́му імі́я і моли́твенника тепла́, із глубини́ душі́ тебі́, покрови́телю, глаго́лем:","Ра́дуйся, промишле́нія Бо́жия о лю́діх ісполни́телю;","ра́дуйся, сокро́вище сокрове́нноє обріти́й і участники себі́ мно́гі сотвори́вий;","ра́дуйся, Ца́рствія Бо́жия наслі́дниче і іни́м моли́твами твої́ми две́рі отверза́яй;","ра́дуйся, всю жизнь со Христо́м соображавий і в нічесо́мже от Него́ отставий;","ра́дуйся, ді́лателю во виногра́ді Христо́вом;","ра́дуйся, немощни́х си́ло о Го́споді;","ра́дуйся, іскуша́ємих ско́рий о Го́споді покро́в і заступле́ніє;","ра́дуйся, унивающим ободре́ніє і скорб'я́щим ра́досте.","Ра́дуйся, о́тче Пафну́тіє, Боровський чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє а́нгельськоє сли́шашеся во святі́м преставле́нії, о́тче, святи́я і богоуго́дния душі́ твоєя́, в небе́сная селе́нія пресла́вно восходя́щия, го́рнія бо си́ли ра́дующеся сріта́ху тя, пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Бо́жиєм світоли́тієм просвіще́н бив, о́тче, я́ко мо́лнія гро́зная блистал єси́, гоня́ і поража́я де́мони, я́коже і от жени́ ні́кия отгна́л єси́ їх: бі́си бо явля́ющеся, устрашаху ю, чесо́ ра́ди смуща́шеся умо́м і боля́ше; овогда́ ви́дяше явля́ющася ста́рця: низька і согбенна, браду́ іму́ща седу і вели́ку, худи́ми ри́зами оді́янна, со вла́стію отгоня́юща де́мони, і бива́ше здра́ва. Сли́ша і глас: Пафну́тій, і́же в Боровскі, отго́нить от тебе́ бі́си. Нете́рпить бо спади́й денни́ця і тайниє клевре́ти єго́ не то́чію присутствія, но і моли́тв смире́нія твоєго́. Ми же, ві́дуще сія́, мо́лим тя: сохраня́й і нас от злоб їх, да хо́дим во сві́ті за́повідей Бо́жиїх, вопію́щия ті усе́рдно:","Ра́дуйся, іді́же осіня́єть благода́ть твоя́, о́тче, отту́ду прого́ниться дия́воля си́ла;","ра́дуйся, освобождаяй прибіга́ющих под кров твой от злих духо́в;","ра́дуйся, неуси́пний стра́же оби́телі твоєя́;","ра́дуйся, душ і тіле́с на́ших благи́й храни́телю;","ра́дуйся, втори́й наш о́бщий а́нгеле;","ра́дуйся, в час сме́ртний заступа́яй лю́б'ящих тя пред Бо́гом;","ра́дуйся, ізимаяй от мита́рств душі́ їх;","ра́дуйся, недаяй впа́сти в ру́ці бісо́м;","ра́дуйся, воздвиза́яй ві́рних к покая́нію і с Бо́гом соєдиняяй.","Ра́дуйся, о́тче Пафну́тіє, Боровський чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть ве́лію прия́л єси́ от Бо́га, о́тче, я́ко мі́ру потря́сну і прелива́ющуся, по мно́жеству любві́ твоєя́ к Бо́гу і бли́жнім, і́же і яви́ тя реку́, ізлива́ющу струї́ мно́гі, благода́ті тре́бующим, істоча́єши ісціле́нія: ми же, ра́дующеся, вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще сві́тлоє о Бо́зі житіє́ твоє́, хва́лим доброді́телі твоя́, я́ко Свята́го Ду́ха дарова́нія, ублажа́єм свято́є успе́ніє твоє́, почита́єм свяще́нную па́м'ять твою́, зову́ще любо́вію:","Ра́дуйся, в ми́рі я́ко премирен би́вий і мир ві́рою побіди́вий;","ра́дуйся, плоть твою́ Христу́ покори́вий;","ра́дуйся, незло́бія і кро́тости пра́вило;","ра́дуйся, безстра́стія сві́тлий до́ме і смире́нія глубино́;","ра́дуйся, Христо́во благоуха́ніє;","ра́дуйся, засту́пниче наш на небесі́ і на землі́;","ра́дуйся, душ і тіле́с на́ших благи́й храни́телю.","Ра́дуйся, о́тче Пафну́тіє, Боровський чудотво́рче."]},{"h":"Кондак 13","ps":["О пресвяти́й і преди́вний о́тче Пафну́тіє, уті́шителю скорб'я́щих, прийми́ сіє́ на́ше ма́лоє моле́ніє, ізба́ви ж нас от вся́ких бід і ві́чния ізми́ муки́, богоприя́тним твої́м пред Бо́гом хода́тайством, да с тобо́ю во ві́ки воспіва́єм: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць, прови́дя тя а́нгелом подража́теля во пло́ті іму́ща би́ти, от ю́на во́зраста облече́ тя во а́нгельський чин. Ти же отше́д от ми́ра і обле́кся во і́ночеськоє одія́ніє, крест на ра́мо взем, вседу́шно поте́кл єси́ во слід Распеншегося нас ра́ди Го́спода: скорб і труд возлюби́в, приліпи́лся єси́ Христу́ любо́вію і моли́твами. Ми же, благодаря́ще о сем Бо́га, похва́льная воспису́єм ті:","Ра́дуйся, послу́шателю Го́спода зову́ща: возьмі́те і́го моє́ на себі́;","ра́дуйся подви́жниче, по́двигом до́брим подвиза́вийся;","ра́дуйся, ізбра́вий путь ті́сний, веду́щий в живо́т;","ра́дуйся, смире́нієм висо́ких дости́гший.","Ра́дуйся, кротостью в зе́млю кро́тких всели́вийся;","ра́дуйся, ві́чноє ра́дованіє на небесі́ обрі́тший.","Ра́дуйся, засту́пниче наш, і нас помина́яй пред Бо́гом ра́дующихся о тебі́.","Ра́дуйся, о́тче Пафну́тіє, Боровський чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче, вели́кий уго́дниче Христо́в, врачу́ благода́тний, бісо́в прогони́телю, всім любо́вію притекающим істоча́яй ми́лости ми́ро, восхваля́єм тя любо́вію, о́тче Пафну́тіє, ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, о́тче Пафну́тіє, Боровський чудотво́рче."]},{"h":"Молитва","ps":["О, свяще́нная главо́, земни́й А́нгеле, Небе́сний челові́че, вели́кий чудотво́рче, преподо́бне о́тче наш Пафну́тіє! К тебі́ с ві́рою і любо́вію усе́рдно прибіга́єм і умиле́нно про́сим: яви́ нам смире́нним і грі́шним свято́є і многомо́щноє твоє́ заступле́ніє. Не дерза́єм, гріх ра́ди на́ших, с свобо́дою чад Бо́жиїх, проси́ти Го́спода і Влади́ку на́шего о поми́лованії і проще́нії. Но тебі́, моли́твенника к Нему́ благоприя́тна, предлага́єм і мо́лим, іспроси́ нам у бла́гости Єго́ да́ри благопотре́бния і спаси́тельния душа́м на́шим: ві́ру пра́ву, благоче́стіє крі́пкоє, покая́ніє і́стинноє, проще́ніє гріхо́в, житіє́ соверше́нноє, ісправле́ніє ріши́тельноє, да обрати́вшеся от злих діл к Богоугожде́нію, про́чеє непрогневля́єм Го́спода наруше́нієм святи́х Єго́ за́повідей. Умоли́, свя́тче Бо́жий, Всеви́шняго Творця́ дарова́ти мир і благоче́стіє страні́ на́шей правосла́вной. Сохрани́, уго́дниче Христо́в, святу́ю оби́тель твою́, созда́нную тобо́ю, і вся живу́щия і подвиза́ющіяся в ней от вся́каго зла ненаві́тни. При́зри ми́лостивно на лю́ди, к тебі́ прибега́ющия, і вся проше́нія їх во благо́є іспо́лни. Всім же нам здра́віє душе́вноє і тіле́сноє, землі́ плодоно́сіє, ти́хоє і благоуго́дноє житіє́, благу́ю, христия́нськую кончи́ну і до́брий отві́т на Стра́шном Суді́ у Всеми́лостиваго Бо́га ісхода́тайствуй, я́ко воі́стину імі́яй ве́ліє к Нему́ дерзнове́ніє. Єй, о́тче, ві́ми, я́ко мно́го мо́жеть моли́тва твоя́ пред лице́м Вседержи́теля Го́спода і нічто́же невозмо́жно єсть хода́тайству твоєму́, а́ще то́кмо восхо́щеши: сего́ ра́ди крі́пко на тя упова́єм і на твої́ святи́я моли́тви вельми́ наді́ємся, я́ко ти приведе́ши нас предста́тельством твої́м в ти́хоє приста́нище спасе́нія і наслі́дники яви́ши ни сві́тлаго Ца́рствія Христо́ва. Не посрами́ же упова́нія на́шего, чудотво́рче святи́й. І сподо́би нас вку́пі с тобо́ю блаже́нства ра́йськаго наслажда́тися, да сла́вим, хва́лим і велича́єм вели́кую ми́лость к нам Человіколю́бця Бо́га, Отця́ і Си́на і Свята́го Ду́ха і твоє́ благо́є, оте́чеськоє заступле́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Житія́ сві́тлостію просвіти́в твоє́ оте́чество, / в моли́твах і пості́х дарова́ній Боже́ственнаго Ду́ха іспо́лнился єси́, / і, во вре́менній сей жи́зні до́брі подвиза́вся, / ми́лость благоутро́бія всім скорб'я́щим отве́рзл єси́, / і ни́щим бил єси́ засту́пник. / Тім мо́лим тя, о́тче Пафну́тіє, // моли́ Христа́ Бо́га, да спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 8","ps":["Бо́жиїм світоли́тієм просвіще́н, о́тче, / по́стничеськоє стяжа́л єси́ жи́тельство, преподо́бне, / і́ноком предо́брий наста́вниче і по́стником благо́є украше́ніє. / Сего́ ра́ди Госпо́дь, труди́ твоя́ ви́дів, / чуде́с да́ром обогати́ тя, / істоча́єши бо ісціле́нія. / Ми же, ра́дующеся, вопіє́м ті: // ра́дуйся, о́тче Пафну́тіє."]}],"notes":[]}];
export default D;
